Object.assign(window.IND_FEED_BODY, {"gv-14-26":{"route":"#/gitav/14.26","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:26:en","title":"Bhagavad Gita 14.26","text":"मां च योऽव्यभिचारेण भक्तियोगेन सेवते ।\nस गुणान्समतीत्यैतान् ब्रह्मभूयाय कल्पते ॥","lang":"sa","roman":"māṃ ca yo’vyabhicāreṇa bhaktiyogena sevate |\nsa guṇānsamatītyaitān brahmabhūyāya kalpate ||","body":"And he who serveth Me exclusively by the Yoga of devotion, he, crossing beyond the qualities, he is fit to become the Eternal.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","26 of 27"]]},"g2-14-26":{"route":"#/gitav/14.26","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:26:en2","title":"Gita 14.26, in another translation","body":"And he who serves Me with an unswerving devotion, he, going beyond the Gunas, is fitted for becoming Brahman.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","26 of 27"]]},"gv-14-27":{"route":"#/gitav/14.27","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:27:en","title":"Bhagavad Gita 14.27","text":"ब्रह्मणो हि प्रतिष्ठाऽहममृतस्याव्ययस्य च ।\nशाश्वतस्य च धर्मस्य सुखस्यैकान्तिकस्य च ॥","lang":"sa","roman":"brahmaṇo hi pratiṣṭhā’hamamṛtasyāvyayasya ca |\nśāśvatasya ca dharmasya sukhasyaikāntikasya ca ||","body":"For I am the abode of the Eternal, and of the indestructible nectar of immortality, of immemorial righteousness, and of unending bliss.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","27 of 27"]]},"g2-14-27":{"route":"#/gitav/14.27","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 14 — The Discrimination of the Three Gunas","src":"gita:14:27:en2","title":"Gita 14.27, in another translation","body":"For I am the abode of Brahman, the Immortal and Immutable, of everlasting Dharma and of Absolute Bliss.","facts":[["Chapter","The Discrimination of the Three Gunas"],["Verse","27 of 27"]]},"gv-15-1":{"route":"#/gitav/15.1","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:1:en","title":"Bhagavad Gita 15.1","text":"ऊर्ध्वमूलमधःशाखमश्वत्थं प्राहुरव्ययम् ।\nछन्दांसि यस्य पर्णानि यस्तं वेद स वेदवित् ॥","lang":"sa","roman":"ūrdhvamūlamadhaḥśākhamaśvatthaṃ prāhuravyayam |\nchandāṃsi yasya parṇāni yastaṃ veda sa vedavit ||","body":"The Blessed Lord said: With roots above, branches below, the Asvattha is said to be indestructible; the leaves of it are hymns; he who knoweth it is a Veda-knower.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","1 of 20"]]},"g2-15-1":{"route":"#/gitav/15.1","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:1:en2","title":"Gita 15.1, in another translation","body":"They speak of an eternal Ashvattha rooted above and branching below, whose leaves are the Vedas; he who knows it, is a Veda-knower.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","1 of 20"]]},"gv-15-2":{"route":"#/gitav/15.2","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:2:en","title":"Bhagavad Gita 15.2","text":"अधश्चोर्ध्वं प्रसृतास्तस्य शाखा गुणप्रवृद्धा विषयप्रवालाः ।\nअधश्च मूलान्यनुसन्ततानि कर्मानुबन्धीनि मनुष्यलोके ॥","lang":"sa","roman":"adhaścordhvaṃ prasṛtāstasya śākhā guṇapravṛddhā viṣayapravālāḥ |\nadhaśca mūlānyanusantatāni karmānubandhīni manuṣyaloke ||","body":"Downwards and upwards spread the branches of it, nourished by the qualities; the objects of the senses its buds; and its roots grow downwards, the bonds of action in the world of men.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","2 of 20"]]},"g2-15-2":{"route":"#/gitav/15.2","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:2:en2","title":"Gita 15.2, in another translation","body":"Below and above spread its branches, nourished by the Gunas; sense-objects are its buds; and below in the world of man stretch forth the roots, originating action.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","2 of 20"]]},"gv-15-3":{"route":"#/gitav/15.3","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:3:en","title":"Bhagavad Gita 15.3","text":"न रूपमस्येह तथोपलभ्यते नान्तो न चादिर्न च संप्रतिष्ठा ।\nअश्वत्थमेनं सुविरूढमूल मसङ्गशस्त्रेण दृढेन छित्त्वा ॥","lang":"sa","roman":"na rūpamasyeha tathopalabhyate nānto na cādirna ca saṃpratiṣṭhā |\naśvatthamenaṃ suvirūḍhamūla masaṅgaśastreṇa dṛḍhena chittvā ||","body":"Nor here may be acquired knowledge of its form, nor its end, nor its origin, nor its rooting-place; this strongly rooted Asvattha having been cut down by the unswerving weapon of non-attachment,","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","3 of 20"]]},"g2-15-3":{"route":"#/gitav/15.3","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:3:en2","title":"Gita 15.3, in another translation","body":"Its form is not here perceived as such, neither its end, nor its origin, nor its existence. Having cut asunder this firm-rooted Ashvattha with the strong axe of non-attachment,—then that Goal is to be sought for, going whither they (the wise) do not return again. I seek refuge in that Primeval Purusha whence streamed forth the Eternal Activity.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","3 of 20"]]},"gv-15-4":{"route":"#/gitav/15.4","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:4:en","title":"Bhagavad Gita 15.4","text":"ततः पदं तत्परिमार्गितव्यं यस्मिन्गता न निवर्तन्ति भूयः ।\nतमेव चाद्यं पुरुषं प्रपद्ये यतः प्रवृत्तिः प्रसृता पुराणी ॥","lang":"sa","roman":"tataḥ padaṃ tatparimārgitavyaṃ yasmingatā na nivartanti bhūyaḥ |\ntameva cādyaṃ puruṣaṃ prapadye yataḥ pravṛttiḥ prasṛtā purāṇī ||","body":"That path beyond may be sought, treading which there is no return. I go indeed to that Primal Man, whence the ancient energy forth-streamed.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","4 of 20"]]},"gv-15-5":{"route":"#/gitav/15.5","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:5:en","title":"Bhagavad Gita 15.5","text":"निर्मानमोहा जितसङ्गदोषा अध्यात्मनित्या विनिवृत्तकामाः ।\nद्वन्द्वैर्विमुक्ताः सुखदुःखसंज्ञै र्गच्छन्त्यमूढाः पदमव्ययं तत् ॥","lang":"sa","roman":"nirmānamohā jitasaṅgadoṣā adhyātmanityā vinivṛttakāmāḥ |\ndvandvairvimuktāḥ sukhaduḥkhasaṃjñai rgacchantyamūḍhāḥ padamavyayaṃ tat ||","body":"Without pride and delusion, victorious over the vice of attachment, dwelling constantly in the Self, desire pacified, liberated from the pairs of opposites known as pleasure and pain, they tread, undeluded, that indestructible path.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","5 of 20"]]},"g2-15-5":{"route":"#/gitav/15.5","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:5:en2","title":"Gita 15.5, in another translation","body":"Free from pride and delusion, with the evil of attachment conquered, ever dwelling in the Self, with desires completely receded, liberated from the pairs of opposites known as pleasure and pain, the undeluded reach that Goal Eternal.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","5 of 20"]]},"gv-15-6":{"route":"#/gitav/15.6","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:6:en","title":"Bhagavad Gita 15.6","text":"न तद्भासयते सूर्यो न शशाङ्को न पावकः ।\nयद्गत्वा न निवर्तन्ते तद्धाम परमं मम ॥","lang":"sa","roman":"na tadbhāsayate sūryo na śaśāṅko na pāvakaḥ |\nyadgatvā na nivartante taddhāma paramaṃ mama ||","body":"Nor doth the sun lighten there, nor moon, nor fire; having gone thither they return not; that is My supreme abode.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","6 of 20"]]},"g2-15-6":{"route":"#/gitav/15.6","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:6:en2","title":"Gita 15.6, in another translation","body":"That the sun illumines not, nor the moon, nor fire; that is My Supreme Abode, going whither they return not.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","6 of 20"]]},"gv-15-7":{"route":"#/gitav/15.7","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:7:en","title":"Bhagavad Gita 15.7","text":"ममैवांशो जीवलोके जीवभूतः सनातनः ।\nमनःषष्ठानीन्द्रियाणि प्रकृतिस्थानि कर्षति ॥","lang":"sa","roman":"mamaivāṃśo jīvaloke jīvabhūtaḥ sanātanaḥ |\nmanaḥṣaṣṭhānīndriyāṇi prakṛtisthāni karṣati ||","body":"A portion of Mine own Self, transformed in the world of life into an immortal Spirit, draweth round itself the senses of which the mind is the sixth, veiled in matter.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","7 of 20"]]},"g2-15-7":{"route":"#/gitav/15.7","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:7:en2","title":"Gita 15.7, in another translation","body":"An eternal portion of Myself having become a living soul in the world of life, draws (to itself) the (five) senses with mind for the sixth, abiding in Prakriti.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","7 of 20"]]},"gv-15-8":{"route":"#/gitav/15.8","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:8:en","title":"Bhagavad Gita 15.8","text":"शरीरं यदवाप्नोति यच्चाप्युत्क्रामतीश्वरः ।\nगृहीत्वैतानि संयाति वायुर्गन्धानिवाशयात् ॥","lang":"sa","roman":"śarīraṃ yadavāpnoti yaccāpyutkrāmatīśvaraḥ |\ngṛhītvaitāni saṃyāti vāyurgandhānivāśayāt ||","body":"When the Lord acquireth a body and when He abandoneth it, He seizeth these and goeth with them, as the wind takes fragrances from their retreats","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","8 of 20"]]},"g2-15-8":{"route":"#/gitav/15.8","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:8:en2","title":"Gita 15.8, in another translation","body":"When the Lord obtains a body and when He leaves it, He takes these and goes, as the wind takes the scents from their seats (the flowers).","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","8 of 20"]]},"gv-15-9":{"route":"#/gitav/15.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:9:en","title":"Bhagavad Gita 15.9","text":"श्रोत्रं चक्षुः स्पर्शनं च रसनं घ्राणमेव च ।\nअधिष्ठाय मनश्चायं विषयानुपसेवते ॥","lang":"sa","roman":"śrotraṃ cakṣuḥ sparśanaṃ ca rasanaṃ ghrāṇameva ca |\nadhiṣṭhāya manaścāyaṃ viṣayānupasevate ||","body":"Enshrined in the ear, the eye, the touch, the taste and the smell, and in the mind also, He enjoyeth the objects of the senses","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","9 of 20"]]},"g2-15-9":{"route":"#/gitav/15.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:9:en2","title":"Gita 15.9, in another translation","body":"Presiding over the ear, the eye, the touch, the taste and the smell, as also the mind, He experiences objects.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","9 of 20"]]},"gv-15-10":{"route":"#/gitav/15.10","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:10:en","title":"Bhagavad Gita 15.10","text":"उत्क्रामन्तं स्थितं वापि भुञ्जानं वा गुणान्वितम् ।\nविमूढा नानुपश्यन्ति पश्यन्ति ज्ञानचक्षुषः ॥","lang":"sa","roman":"utkrāmantaṃ sthitaṃ vāpi bhuñjānaṃ vā guṇānvitam |\nvimūḍhā nānupaśyanti paśyanti jñānacakṣuṣaḥ ||","body":"The deluded do not perceive (Him) when He departeth or stayeth or enjoyeth, swayed by the qualities; the wisdom-eyed perceive.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","10 of 20"]]},"g2-15-10":{"route":"#/gitav/15.10","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:10:en2","title":"Gita 15.10, in another translation","body":"Him while transmigrating from one body to another, or residing (in the same) or experiencing, or when united with the Gunas,—the deluded do not see; but those who have the eye of wisdom behold Him.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","10 of 20"]]},"gv-15-11":{"route":"#/gitav/15.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:11:en","title":"Bhagavad Gita 15.11","text":"यतन्तो योगिनश्चैनं पश्यन्त्यात्मन्यवस्थितम् ।\nयतन्तोऽप्यकृतात्मानो नैनं पश्यन्त्यचेतसः ॥","lang":"sa","roman":"yatanto yoginaścainaṃ paśyantyātmanyavasthitam |\nyatanto’pyakṛtātmāno nainaṃ paśyantyacetasaḥ ||","body":"Yogîs also, struggling, perceive Him, established in the Self; but though struggling, the unintelligent perceive Him not, their selves untrained.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","11 of 20"]]},"g2-15-11":{"route":"#/gitav/15.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:11:en2","title":"Gita 15.11, in another translation","body":"The Yogis striving (for perfection) behold Him dwelling in themselves; but the unrefined and unintelligent, even though striving, see Him not.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","11 of 20"]]},"gv-15-12":{"route":"#/gitav/15.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:12:en","title":"Bhagavad Gita 15.12","text":"यदादित्यगतं तेजो जगद्भासयतेऽखिलम् ।\nयच्चन्द्रमसि यच्चाग्नौ तत्तेजो विद्धि मामकम् ॥","lang":"sa","roman":"yadādityagataṃ tejo jagadbhāsayate’khilam |\nyaccandramasi yaccāgnau tattejo viddhi māmakam ||","body":"That splendour issuing from the sun that enlighteneth the whole world, that which is in the moon and in fire, that splendour know as from Me.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","12 of 20"]]},"g2-15-12":{"route":"#/gitav/15.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:12:en2","title":"Gita 15.12, in another translation","body":"The light which, residing in the sun illumines the whole world, that which is in the moon and in the fire—know that light to be Mine.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","12 of 20"]]},"gv-15-13":{"route":"#/gitav/15.13","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:13:en","title":"Bhagavad Gita 15.13","text":"गामाविश्य च भूतानि धारयाम्यहमोजसा ।\nपुष्णामि चौषधीः सर्वाः सोमो भूत्वा रसात्मकः ॥","lang":"sa","roman":"gāmāviśya ca bhūtāni dhārayāmyahamojasā |\npuṣṇāmi cauṣadhīḥ sarvāḥ somo bhūtvā rasātmakaḥ ||","body":"Permeating the soil, I support beings by my vital energy, and having become the delicious Soma I nourish all plants.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","13 of 20"]]},"g2-15-13":{"route":"#/gitav/15.13","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:13:en2","title":"Gita 15.13, in another translation","body":"Entering the earth with My energy, I support all beings, and I nourish all the herbs, becoming the watery moon.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","13 of 20"]]},"gv-15-14":{"route":"#/gitav/15.14","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:14:en","title":"Bhagavad Gita 15.14","text":"अहं वैश्वानरो भूत्वा प्राणिनां देहमाश्रितः ।\nप्राणापानसमायुक्तः पचाम्यन्नं चतुर्विधम् ॥","lang":"sa","roman":"ahaṃ vaiśvānaro bhūtvā prāṇināṃ dehamāśritaḥ |\nprāṇāpānasamāyuktaḥ pacāmyannaṃ caturvidham ||","body":"I, having become the Fire of Life, take possession of the bodies of breathing things, and united with the life-breaths, I digest the four kinds of food.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","14 of 20"]]},"g2-15-14":{"route":"#/gitav/15.14","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:14:en2","title":"Gita 15.14, in another translation","body":"Abiding in the body of living beings as (the fire) Vaishvânara, I, associated with Prâna and Apâna, digest the fourfold food.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","14 of 20"]]},"gv-15-15":{"route":"#/gitav/15.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:15:en","title":"Bhagavad Gita 15.15","text":"सर्वस्य चाहं हृदि सन्निविष्टो मत्तः स्मृतिर्ज्ञानमपोहनं च ।\nवेदैश्च सर्वैरहमेव वेद्यो वेदान्तकृद्वेदविदेव चाहम् ॥","lang":"sa","roman":"sarvasya cāhaṃ hṛdi sanniviṣṭo mattaḥ smṛtirjñānamapohanaṃ ca |\nvedaiśca sarvairahameva vedyo vedāntakṛdvedavideva cāham ||","body":"And I am seated in the hearts of all, and from Me memory and wisdom and their absence. And that which is to be known in all the Vedas am I; and I indeed the Veda-knower and the author of the Vedanta.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","15 of 20"]]},"g2-15-15":{"route":"#/gitav/15.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:15:en2","title":"Gita 15.15, in another translation","body":"I am centred in the hearts of all; memory and perception as well as their loss come from Me. I am verily that which has to be known by all the Vedas, I indeed am the Author of the Vedânta, and the Knower of the Veda am I.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","15 of 20"]]},"gv-15-16":{"route":"#/gitav/15.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:16:en","title":"Bhagavad Gita 15.16","text":"द्वाविमौ पुरुषौ लोके क्षरश्चाक्षर एव च ।\nक्षरः सर्वाणि भूतानि कूटस्थोऽक्षर उच्यते ॥","lang":"sa","roman":"dvāvimau puruṣau loke kṣaraścākṣara eva ca |\nkṣaraḥ sarvāṇi bhūtāni kūṭastho’kṣara ucyate ||","body":"There are two Energies in this world, the destructible and the indestructible; the destructible is all beings, the unchanging is called the indestructible.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","16 of 20"]]},"g2-15-16":{"route":"#/gitav/15.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:16:en2","title":"Gita 15.16, in another translation","body":"There are two Purushas in the world,—the Perishable and the Imperishable. All beings are the Perishable; and the Kutastha is called Imperishable.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","16 of 20"]]},"gv-15-17":{"route":"#/gitav/15.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:17:en","title":"Bhagavad Gita 15.17","text":"उत्तमः पुरुषस्त्वन्यः परमात्मेत्युदाहृतः ।\nयो लोकत्रयमाविश्य बिभर्त्यव्यय ईश्वरः ॥","lang":"sa","roman":"uttamaḥ puruṣastvanyaḥ paramātmetyudāhṛtaḥ |\nyo lokatrayamāviśya bibhartyavyaya īśvaraḥ ||","body":"The highest Energy is verily Another, declared as the Supreme Self, He who, pervading all, sustaineth the three worlds, the indestructible Lord.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","17 of 20"]]},"g2-15-17":{"route":"#/gitav/15.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:17:en2","title":"Gita 15.17, in another translation","body":"But (there is) another, the Supreme Purusha, called the Highest Self, the immutable Lord, who pervading the three worlds, sustains them.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","17 of 20"]]},"gv-15-18":{"route":"#/gitav/15.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:18:en","title":"Bhagavad Gita 15.18","text":"यस्मात्क्षरमतीतोऽहमक्षरादपि चोत्तमः ।\nअतोऽस्मि लोके वेदे च प्रथितः पुरुषोत्तमः ॥","lang":"sa","roman":"yasmātkṣaramatīto’hamakṣarādapi cottamaḥ |\nato’smi loke vede ca prathitaḥ puruṣottamaḥ ||","body":"Since I excel the destructible, and am more excellent also than the indestructible, in the world and in the Veda I am proclaimed the Supreme Spirit.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","18 of 20"]]},"g2-15-18":{"route":"#/gitav/15.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:18:en2","title":"Gita 15.18, in another translation","body":"As I transcend the Perishable and am above even the Imperishable, therefore am I in the world and in the Veda celebrated as the Purushottama, (the Highest Purusha).","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","18 of 20"]]},"gv-15-19":{"route":"#/gitav/15.19","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:19:en","title":"Bhagavad Gita 15.19","text":"यो मामेवमसम्मूढो जानाति पुरुषोत्तमम् ।\nस सर्वविद्भजति मां सर्वभावेन भारत ॥","lang":"sa","roman":"yo māmevamasammūḍho jānāti puruṣottamam |\nsa sarvavidbhajati māṃ sarvabhāvena bhārata ||","body":"He who undeluded knoweth Me thus as the Supreme Spirit, he, all-knowing, worshippeth Me with his whole being, O Bhârata.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","19 of 20"]]},"g2-15-19":{"route":"#/gitav/15.19","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:19:en2","title":"Gita 15.19, in another translation","body":"He who free from delusion thus knows Me, the Highest Spirit, he knowing all, worships Me with all his heart, O descendant of Bharata.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","19 of 20"]]},"gv-15-20":{"route":"#/gitav/15.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:20:en","title":"Bhagavad Gita 15.20","text":"इति गुह्यतमं शास्त्रमिदमुक्तं मयाऽनघ ।\nएतद्बुद्ध्वा बुद्धिमान्स्यात्कृतकृत्यश्च भारत ॥","lang":"sa","roman":"iti guhyatamaṃ śāstramidamuktaṃ mayā’nagha |\netadbuddhvā buddhimānsyātkṛtakṛtyaśca bhārata ||","body":"Thus by Me this most secret teaching hath been told O sinless one. This known, he hath become illuminated and hath finished his work, O Bhârata.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","20 of 20"]]},"g2-15-20":{"route":"#/gitav/15.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 15 — The Way to the Supreme Spirit","src":"gita:15:20:en2","title":"Gita 15.20, in another translation","body":"Thus, O sinless one, has this most profound teaching been imparted by Me. Knowing this one attains the highest intelligence and will have accomplished all one's duties, O descendant of Bharata.","facts":[["Chapter","The Way to the Supreme Spirit"],["Verse","20 of 20"]]},"gv-16-1":{"route":"#/gitav/16.1","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:1:en","title":"Bhagavad Gita 16.1","text":"अभयं सत्त्वसंशुद्धिर्ज्ञानयोगव्यवस्थितिः ।\nदानं दमश्च यज्ञश्च स्वाध्यायस्तप आर्जवम् ॥","lang":"sa","roman":"abhayaṃ sattvasaṃśuddhirjñānayogavyavasthitiḥ |\ndānaṃ damaśca yajñaśca svādhyāyastapa ārjavam ||","body":"The Blessed Lord said: Fearlessness, cleanness of life, steadfastness in the Yoga of wisdom, almsgiving, self-restraint and sacrifice and study of the Scriptures, austerity and straightforwardness,","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","1 of 24"]]},"g2-16-1":{"route":"#/gitav/16.1","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:1:en2","title":"Gita 16.1, in another translation","body":"Fearlessness, purity of heart, steadfastness in knowledge and Yoga; almsgiving, control of the senses, Yajna, reading of the Shâstras, austerity, uprightness;","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","1 of 24"]]},"gv-16-2":{"route":"#/gitav/16.2","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:2:en","title":"Bhagavad Gita 16.2","text":"अहिंसा सत्यमक्रोधस्त्यागः शान्तिरपैशुनम् ।\nदया भूतेष्वलोलुप्त्वं मार्दवं ह्रीरचापलम् ॥","lang":"sa","roman":"ahiṃsā satyamakrodhastyāgaḥ śāntirapaiśunam |\ndayā bhūteṣvaloluptvaṃ mārdavaṃ hrīracāpalam ||","body":"Harmlessness, truth, absence of wrath, renunciation, peacefulness, absence of crookedness, compassion to living beings, uncovetousness, mildness, modesty, absence of fickleness,","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","2 of 24"]]},"g2-16-2":{"route":"#/gitav/16.2","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:2:en2","title":"Gita 16.2, in another translation","body":"Non-injury, truth, absence of anger, renunciation, tranquillity, absence of calumny, compassion to beings, un-covetousness, gentleness, modesty, absence of fickleness;","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","2 of 24"]]},"gv-16-3":{"route":"#/gitav/16.3","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:3:en","title":"Bhagavad Gita 16.3","text":"तेजः क्षमा धृतिः शौचमद्रोहो नातिमानिता ।\nभवन्ति सम्पदं दैवीमभिजातस्य भारत ॥","lang":"sa","roman":"tejaḥ kṣamā dhṛtiḥ śaucamadroho nātimānitā |\nbhavanti sampadaṃ daivīmabhijātasya bhārata ||","body":"Vigour, forgiveness, fortitude, purity, absence of envy and pride—these are his who is born with the divine properties, O Bhârata.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","3 of 24"]]},"g2-16-3":{"route":"#/gitav/16.3","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:3:en2","title":"Gita 16.3, in another translation","body":"Boldness, forgiveness, fortitude, purity, absence of hatred, absence of pride; these belong to one born for a divine state, O descendant of Bharata.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","3 of 24"]]},"gv-16-4":{"route":"#/gitav/16.4","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:4:en","title":"Bhagavad Gita 16.4","text":"दम्भो दर्पोऽभिमानश्च क्रोधः पारुष्यमेव च ।\nअज्ञानं चाभिजातस्य पार्थ सम्पदमासुरीम् ॥","lang":"sa","roman":"dambho darpo’bhimānaśca krodhaḥ pāruṣyameva ca |\najñānaṃ cābhijātasya pārtha sampadamāsurīm ||","body":"Hypocrisy, arrogance and conceit, wrath and also harshness and unwisdom are his who is born, O Pârtha, with demoniacal properties.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","4 of 24"]]},"g2-16-4":{"route":"#/gitav/16.4","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:4:en2","title":"Gita 16.4, in another translation","body":"Ostentation, arrogance and self-conceit, anger as also harshness and ignorance, belong to one who is born, O Pârtha, for an Asurika state.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","4 of 24"]]},"gv-16-5":{"route":"#/gitav/16.5","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:5:en","title":"Bhagavad Gita 16.5","text":"दैवी सम्पद्विमोक्षाय निबन्धायासुरी मता ।\nमा शुचः सम्पदं दैवीमभिजातोऽसि पाण्डव ॥","lang":"sa","roman":"daivī sampadvimokṣāya nibandhāyāsurī matā |\nmā śucaḥ sampadaṃ daivīmabhijāto’si pāṇḍava ||","body":"The divine properties are deemed to be for liberation, the demoniacal for bondage. Grieve not, thou art born with divine properties, O Pândava.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","5 of 24"]]},"g2-16-5":{"route":"#/gitav/16.5","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:5:en2","title":"Gita 16.5, in another translation","body":"The divine state is deemed to make for liberation, the Asurika for bondage; grieve not, O Pândava, thou art born for a divine state.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","5 of 24"]]},"gv-16-6":{"route":"#/gitav/16.6","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:6:en","title":"Bhagavad Gita 16.6","text":"द्वौ भूतसर्गौ लोकेऽस्मिन्दैव आसुर एव च ।\nदैवो विस्तरशः प्रोक्त आसुरं पार्थ मे शृणु ॥","lang":"sa","roman":"dvau bhūtasargau loke’smindaiva āsura eva ca |\ndaivo vistaraśaḥ prokta āsuraṃ pārtha me śṛṇu ||","body":"Twofold is the animal creation in this world, the divine and the demoniacal: the divine hath been described at length: hear from Me, O Pârtha, the demoniacal.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","6 of 24"]]},"g2-16-6":{"route":"#/gitav/16.6","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:6:en2","title":"Gita 16.6, in another translation","body":"There are two types of beings in this world, the divine and the Asurika. The divine have been described at length; hear from Me, O Pârtha, of the Asurika.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","6 of 24"]]},"gv-16-7":{"route":"#/gitav/16.7","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:7:en","title":"Bhagavad Gita 16.7","text":"प्रवृत्तिं च निवृत्तिं च जना न विदुरासुराः ।\nन शौचं नापि चाचारो न सत्यं तेषु विद्यते ॥","lang":"sa","roman":"pravṛttiṃ ca nivṛttiṃ ca janā na vidurāsurāḥ |\nna śaucaṃ nāpi cācāro na satyaṃ teṣu vidyate ||","body":"Demoniacal men know neither right energy nor right abstinence; nor purity, nor even propriety, nor truth is in them.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","7 of 24"]]},"g2-16-7":{"route":"#/gitav/16.7","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:7:en2","title":"Gita 16.7, in another translation","body":"The persons of Asurika nature know not what to do and what to refrain from; neither is purity found in them nor good conduct, nor truth.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","7 of 24"]]},"gv-16-8":{"route":"#/gitav/16.8","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:8:en","title":"Bhagavad Gita 16.8","text":"असत्यमप्रतिष्ठं ते जगदाहुरनीश्वरम् ।\nअपरस्परसम्भूतं किमन्यत्कामहैतुकम् ॥","lang":"sa","roman":"asatyamapratiṣṭhaṃ te jagadāhuranīśvaram |\naparasparasambhūtaṃ kimanyatkāmahaitukam ||","body":"\"The universe is without truth, without basis,\" they say, \"without a God; brought about by mutual union, and caused by lust and nothing else.\"","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","8 of 24"]]},"g2-16-8":{"route":"#/gitav/16.8","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:8:en2","title":"Gita 16.8, in another translation","body":"They say, \"The universe is without truth, without a (moral) basis, without a God, brought about by mutual union, with lust for its cause; what else?\"","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","8 of 24"]]},"gv-16-9":{"route":"#/gitav/16.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:9:en","title":"Bhagavad Gita 16.9","text":"एतां दृष्टिमवष्टभ्य नष्टात्मानोऽल्पबुद्धयः ।\nप्रभवन्त्युग्रकर्माणः क्षयाय जगतोऽहिताः ॥","lang":"sa","roman":"etāṃ dṛṣṭimavaṣṭabhya naṣṭātmāno’lpabuddhayaḥ |\nprabhavantyugrakarmāṇaḥ kṣayāya jagato’hitāḥ ||","body":"Holding this view, these ruined selves of small understanding, of fierce deeds, come forth as enemies for the destruction of the world.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","9 of 24"]]},"g2-16-9":{"route":"#/gitav/16.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:9:en2","title":"Gita 16.9, in another translation","body":"Holding this view, these ruined souls of small intellect and fierce deeds, rise as the enemies of the world for its destruction.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","9 of 24"]]},"gv-16-10":{"route":"#/gitav/16.10","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:10:en","title":"Bhagavad Gita 16.10","text":"काममाश्रित्य दुष्पूरं दम्भमानमदान्विताः ।\nमोहाद्गृहीत्वासद्ग्राहान्प्रवर्तन्तेऽशुचिव्रताः ॥","lang":"sa","roman":"kāmamāśritya duṣpūraṃ dambhamānamadānvitāḥ |\nmohādgṛhītvāsadgrāhānpravartante’śucivratāḥ ||","body":"Surrendering themselves to insatiable desires, possessed with vanity, conceit and arrogance, holding evil ideas through delusion, they engage in action with impure resolves.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","10 of 24"]]},"g2-16-10":{"route":"#/gitav/16.10","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:10:en2","title":"Gita 16.10, in another translation","body":"Filled with insatiable desires, full of hypocrisy, pride and arrogance, holding evil ideas through delusion, they work with impure resolve.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","10 of 24"]]},"gv-16-11":{"route":"#/gitav/16.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:11:en","title":"Bhagavad Gita 16.11","text":"चिन्तामपरिमेयां च प्रलयान्तामुपाश्रिताः ।\nकामोपभोगपरमा एतावदिति निश्चिताः ॥","lang":"sa","roman":"cintāmaparimeyāṃ ca pralayāntāmupāśritāḥ |\nkāmopabhogaparamā etāvaditi niścitāḥ ||","body":"Giving themselves over to unmeasured thought whose end is death, regarding the gratification of desires as the highest, feeling sure that this is all,","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","11 of 24"]]},"g2-16-11":{"route":"#/gitav/16.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:11:en2","title":"Gita 16.11, in another translation","body":"Beset with immense cares ending only with death, regarding gratification of lust as the highest, and feeling sure that that is all;","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","11 of 24"]]},"gv-16-12":{"route":"#/gitav/16.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:12:en","title":"Bhagavad Gita 16.12","text":"आशापाशशतैर्बद्धाः कामक्रोधपरायणाः ।\nईहन्ते कामभोगार्थमन्यायेनार्थसञ्चयान् ॥","lang":"sa","roman":"āśāpāśaśatairbaddhāḥ kāmakrodhaparāyaṇāḥ |\nīhante kāmabhogārthamanyāyenārthasañcayān ||","body":"Held in bondage by a hundred ties of expectation, given over to lust and anger, they strive to obtain by unlawful means hoards of wealth for sensual enjoyments.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","12 of 24"]]},"g2-16-12":{"route":"#/gitav/16.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:12:en2","title":"Gita 16.12, in another translation","body":"Bound by a hundred ties of hope, given over to lust and wrath, they strive to secure by unjust means hoards of wealth for sensual enjoyment.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","12 of 24"]]},"gv-16-13":{"route":"#/gitav/16.13","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:13:en","title":"Bhagavad Gita 16.13","text":"इदमद्य मया लब्धमिमं प्राप्स्ये मनोरथम् ।\nइदमस्तीदमपि मे भविष्यति पुनर्धनम् ॥","lang":"sa","roman":"idamadya mayā labdhamimaṃ prāpsye manoratham |\nidamastīdamapi me bhaviṣyati punardhanam ||","body":"\"This to-day by me hath been won, that purpose I shall gain; this wealth is mine already, and also this shall be mine in future.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","13 of 24"]]},"g2-16-13":{"route":"#/gitav/16.13","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:13:en2","title":"Gita 16.13, in another translation","body":"\"This to-day has been gained by me; this desire I shall obtain; this is mine, and this wealth also shall be mine in future.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","13 of 24"]]},"gv-16-14":{"route":"#/gitav/16.14","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:14:en","title":"Bhagavad Gita 16.14","text":"असौ मया हतः शत्रुर्हनिष्ये चापरानपि ।\nईश्वरोऽहमहं भोगी सिद्धोऽहं बलवान्सुखी ॥","lang":"sa","roman":"asau mayā hataḥ śatrurhaniṣye cāparānapi |\nīśvaro’hamahaṃ bhogī siddho’haṃ balavānsukhī ||","body":"\"I have slain this enemy, and others also I shall slay. I am the Lord, I am the enjoyer, I am perfect, powerful, happy;","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","14 of 24"]]},"g2-16-14":{"route":"#/gitav/16.14","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:14:en2","title":"Gita 16.14, in another translation","body":"\"That enemy has been slain by me, and others also shall I slay. I am the lord, I enjoy, I am successful, powerful and happy.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","14 of 24"]]},"gv-16-15":{"route":"#/gitav/16.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:15:en","title":"Bhagavad Gita 16.15","text":"आढ्योऽभिजनवानस्मि कोऽन्योऽस्ति सदृशो मया ।\nयक्ष्ये दास्यामि मोदिष्य इत्यज्ञानविमोहिताः ॥","lang":"sa","roman":"āḍhyo’bhijanavānasmi ko’nyo’sti sadṛśo mayā |\nyakṣye dāsyāmi modiṣya ityajñānavimohitāḥ ||","body":"\"I am wealthy, well-born; what other is there that is like unto me? I will sacrifice, I will give alms, I will rejoice.\" Thus deluded by unwisdom,","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","15 of 24"]]},"g2-16-15":{"route":"#/gitav/16.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:15:en2","title":"Gita 16.15, in another translation","body":"\"I am rich and well-born. Who else is equal to me? I will sacrifice, I will give, I will rejoice.\" Thus deluded by ignorance,","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","15 of 24"]]},"gv-16-16":{"route":"#/gitav/16.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:16:en","title":"Bhagavad Gita 16.16","text":"अनेकचित्तविभ्रान्ता मोहजालसमावृताः ।\nप्रसक्ताः कामभोगेषु पतन्ति नरकेऽशुचौ ॥","lang":"sa","roman":"anekacittavibhrāntā mohajālasamāvṛtāḥ |\nprasaktāḥ kāmabhogeṣu patanti narake’śucau ||","body":"Bewildered by numerous thoughts, enmeshed in the web of delusion, addicted to the gratification of desire, they fall downwards into a foul hell.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","16 of 24"]]},"g2-16-16":{"route":"#/gitav/16.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:16:en2","title":"Gita 16.16, in another translation","body":"Bewildered by many a fancy, covered by the meshes of delusion, addicted to the gratification of lust, they fall down into a foul hell.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","16 of 24"]]},"gv-16-17":{"route":"#/gitav/16.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:17:en","title":"Bhagavad Gita 16.17","text":"आत्मसम्भाविताः स्तब्धा धनमानमदान्विताः ।\nयजन्ते नामयज्ञैस्ते दम्भेनाविधिपूर्वकम् ॥","lang":"sa","roman":"ātmasambhāvitāḥ stabdhā dhanamānamadānvitāḥ |\nyajante nāmayajñaiste dambhenāvidhipūrvakam ||","body":"Self-glorifying, stubborn, filled with the pride and intoxication of wealth, they perform lip-sacrifices for ostentation, contrary to scriptural ordinance.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","17 of 24"]]},"g2-16-17":{"route":"#/gitav/16.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:17:en2","title":"Gita 16.17, in another translation","body":"Self-conceited, haughty, filled with the pride and intoxication of wealth, they perform sacrifices in name, out of ostentation, disregarding ordinance;","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","17 of 24"]]},"gv-16-18":{"route":"#/gitav/16.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:18:en","title":"Bhagavad Gita 16.18","text":"अहङ्कारं बलं दर्पं कामं क्रोधं च संश्रिताः ।\nमामात्मपरदेहेषु प्रद्विषन्तोऽभ्यसूयकाः ॥","lang":"sa","roman":"ahaṅkāraṃ balaṃ darpaṃ kāmaṃ krodhaṃ ca saṃśritāḥ |\nmāmātmaparadeheṣu pradviṣanto’bhyasūyakāḥ ||","body":"Given over to egoism, power, insolence, lust and wrath, these malicious ones hate Me in the bodies of others and in their own.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","18 of 24"]]},"g2-16-18":{"route":"#/gitav/16.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:18:en2","title":"Gita 16.18, in another translation","body":"Possessed of egoism, power, insolence, lust and wrath, these malignant people hate Me (the Self within) in their own bodies and those of others.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","18 of 24"]]},"gv-16-19":{"route":"#/gitav/16.19","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:19:en","title":"Bhagavad Gita 16.19","text":"तानहं द्विषतः क्रूरान्संसारेषु नराधमान् ।\nक्षिपाम्यजस्रमशुभानासुरीष्वेव योनिषु ॥","lang":"sa","roman":"tānahaṃ dviṣataḥ krūrānsaṃsāreṣu narādhamān |\nkṣipāmyajasramaśubhānāsurīṣveva yoniṣu ||","body":"These haters, evil, pitiless, vilest among men in the world, I ever throw down into demoniacal wombs.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","19 of 24"]]},"g2-16-19":{"route":"#/gitav/16.19","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:19:en2","title":"Gita 16.19, in another translation","body":"These malicious and cruel evildoers, most degraded of men, I hurl perpetually into the wombs of Asuras only, in these worlds.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","19 of 24"]]},"gv-16-20":{"route":"#/gitav/16.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:20:en","title":"Bhagavad Gita 16.20","text":"आसुरीं योनिमापन्ना मूढा जन्मनि जन्मनि ।\nमामप्राप्यैव कौन्तेय ततो यान्त्यधमां गतिम् ॥","lang":"sa","roman":"āsurīṃ yonimāpannā mūḍhā janmani janmani |\nmāmaprāpyaiva kaunteya tato yāntyadhamāṃ gatim ||","body":"Cast into demoniacal wombs, deluded birth after birth, attaining not to Me, O Kaunteya, they sink into the lowest depths.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","20 of 24"]]},"g2-16-20":{"route":"#/gitav/16.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:20:en2","title":"Gita 16.20, in another translation","body":"Obtaining the Asurika wombs, and deluded birth after birth, not attaining to Me, they thus fall, O son of Kunti, into a still lower condition.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","20 of 24"]]},"gv-16-21":{"route":"#/gitav/16.21","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:21:en","title":"Bhagavad Gita 16.21","text":"त्रिविधं नरकस्येदं द्वारं नाशनमात्मनः ।\nकामः क्रोधस्तथा लोभस्तस्मादेतत्त्रयं त्यजेत् ॥","lang":"sa","roman":"trividhaṃ narakasyedaṃ dvāraṃ nāśanamātmanaḥ |\nkāmaḥ krodhastathā lobhastasmādetattrayaṃ tyajet ||","body":"Triple is the gate of this hell, destructive of the self—lust, wrath, and greed; therefore let man renounce these three.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","21 of 24"]]},"g2-16-21":{"route":"#/gitav/16.21","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:21:en2","title":"Gita 16.21, in another translation","body":"Triple is this gate of hell, destructive of the self,—lust, anger and greed; therefore one should forsake these three.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","21 of 24"]]},"gv-16-22":{"route":"#/gitav/16.22","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:22:en","title":"Bhagavad Gita 16.22","text":"एतैर्विमुक्तः कौन्तेय तमोद्वारैस्त्रिभिर्नरः ।\nआचरत्यात्मनः श्रेयस्ततो याति परां गतिम् ॥","lang":"sa","roman":"etairvimuktaḥ kaunteya tamodvāraistribhirnaraḥ |\nācaratyātmanaḥ śreyastato yāti parāṃ gatim ||","body":"A man liberated from these three gates of darkness, O son of Kunti, accomplisheth his own welfare, and thus reacheth the highest goal.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","22 of 24"]]},"g2-16-22":{"route":"#/gitav/16.22","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:22:en2","title":"Gita 16.22, in another translation","body":"The man who has got beyond these three gates of darkness, O son of Kunti, practises what is good for himself, and thus goes to the Goal Supreme.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","22 of 24"]]},"gv-16-23":{"route":"#/gitav/16.23","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:23:en","title":"Bhagavad Gita 16.23","text":"यः शास्त्रविधिमुत्सृज्य वर्तते कामकारतः ।\nन स सिद्धिमवाप्नोति न सुखं न परां गतिम् ॥","lang":"sa","roman":"yaḥ śāstravidhimutsṛjya vartate kāmakārataḥ |\nna sa siddhimavāpnoti na sukhaṃ na parāṃ gatim ||","body":"He who, having cast aside the ordinances of the Scriptures, followeth the promptings of desire, attaineth not to perfection, nor happiness, nor the highest goal.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","23 of 24"]]},"g2-16-23":{"route":"#/gitav/16.23","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:23:en2","title":"Gita 16.23, in another translation","body":"He who, setting aside the ordinance of the Shâstra, acts under the impulse of desire, attains not to perfection, nor happiness, nor the Goal Supreme.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","23 of 24"]]},"gv-16-24":{"route":"#/gitav/16.24","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:24:en","title":"Bhagavad Gita 16.24","text":"तस्माच्छास्त्रं प्रमाणं ते कार्याकार्यव्यवस्थितौ ।\nज्ञात्वा शास्त्रविधानोक्तं कर्म कर्तुमिहार्हसि ॥","lang":"sa","roman":"tasmācchāstraṃ pramāṇaṃ te kāryākāryavyavasthitau |\njñātvā śāstravidhānoktaṃ karma kartumihārhasi ||","body":"Therefore let the Scriptures be thy authority, in determining what ought to be done, or what ought not to be done. Knowing what hath been declared by the ordinances of the Scriptures, thou oughtest to work in this world.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","24 of 24"]]},"g2-16-24":{"route":"#/gitav/16.24","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 16 — The Classification of the Divine and the Non-divine Attributes","src":"gita:16:24:en2","title":"Gita 16.24, in another translation","body":"So let the Shâstra be thy authority in ascertaining what ought to be done and what ought not to be done. Having known what is said in the ordinance of the Shâstra, thou shouldst act here.","facts":[["Chapter","The Classification of the Divine and the Non-divine Attributes"],["Verse","24 of 24"]]},"gv-17-1":{"route":"#/gitav/17.1","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:1:en","title":"Bhagavad Gita 17.1","text":"ये शास्त्रविधिमुत्सृज्य यजन्ते श्रद्धयाऽन्विताः ।\nतेषां निष्ठा तु का कृष्ण सत्त्वमाहो रजस्तमः ॥","lang":"sa","roman":"ye śāstravidhimutsṛjya yajante śraddhayā’nvitāḥ |\nteṣāṃ niṣṭhā tu kā kṛṣṇa sattvamāho rajastamaḥ ||","body":"Arjuna said: Those that sacrifice full of faith, but casting aside the ordinances of the Scriptures, what is verily their condition, O Krishna? Is it one of Purity, Passion, or Darkness?","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","1 of 28"]]},"g2-17-1":{"route":"#/gitav/17.1","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:1:en2","title":"Gita 17.1, in another translation","body":"Those who setting aside the ordinance of the Shâstra, perform sacrifice with Shraddhâ, what is their condition, O Krishna? (Is it) Sattva, Rajas or Tamas?","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","1 of 28"]]},"gv-17-2":{"route":"#/gitav/17.2","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:2:en","title":"Bhagavad Gita 17.2","text":"त्रिविधा भवति श्रद्धा देहिनां सा स्वभावजा ।\nसात्त्विकी राजसी चैव तामसी चेति तां शृणु ॥","lang":"sa","roman":"trividhā bhavati śraddhā dehināṃ sā svabhāvajā |\nsāttvikī rājasī caiva tāmasī ceti tāṃ śṛṇu ||","body":"The Blessed Lord said: Threefold is by nature the inborn faith of the embodied—pure, passionate, and dark. Hear thou of these.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","2 of 28"]]},"g2-17-2":{"route":"#/gitav/17.2","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:2:en2","title":"Gita 17.2, in another translation","body":"Threefold is the Shraddhâ of the embodied, which is inherent in their nature,—the Sâttvika, the Râjasika and the Tâmasika. Do thou hear of it.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","2 of 28"]]},"gv-17-3":{"route":"#/gitav/17.3","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:3:en","title":"Bhagavad Gita 17.3","text":"सत्त्वानुरूपा सर्वस्य श्रद्धा भवति भारत ।\nश्रद्धामयोऽयं पुरुषो यो यच्छ्रद्धः स एव सः ॥","lang":"sa","roman":"sattvānurūpā sarvasya śraddhā bhavati bhārata |\nśraddhāmayo’yaṃ puruṣo yo yacchraddhaḥ sa eva saḥ ||","body":"The faith of each is shaped to his own nature, O Bhârata. The man consists of his faith; that which his faith is, he is even that.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","3 of 28"]]},"g2-17-3":{"route":"#/gitav/17.3","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:3:en2","title":"Gita 17.3, in another translation","body":"The Shraddhâ of each is according to his natural disposition, O descendant of Bharata. The man consists of his Shraddhâ; he verily is what his Shraddhâ is.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","3 of 28"]]},"gv-17-4":{"route":"#/gitav/17.4","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:4:en","title":"Bhagavad Gita 17.4","text":"यजन्ते सात्त्विका देवान्यक्षरक्षांसि राजसाः ।\nप्रेतान्भूतगणांश्चान्ये यजन्ते तामसा जनाः ॥","lang":"sa","roman":"yajante sāttvikā devānyakṣarakṣāṃsi rājasāḥ |\npretānbhūtagaṇāṃścānye yajante tāmasā janāḥ ||","body":"Pure men worship the Gods; the passionate the gnomes and giants; the others, the dark folk, worship ghosts and troops of nature-spirits.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","4 of 28"]]},"g2-17-4":{"route":"#/gitav/17.4","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:4:en2","title":"Gita 17.4, in another translation","body":"Sâttvika men worship the Devas; Râjasika, the Yakshas and the Râkshasas; the others—the Tâmasika men—the Pretas and the hosts of Bhutas.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","4 of 28"]]},"gv-17-5":{"route":"#/gitav/17.5","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:5:en","title":"Bhagavad Gita 17.5","text":"अशास्त्रविहितं घोरं तप्यन्ते ये तपो जनाः ।\nदम्भाहङ्कारसंयुक्ताः कामरागबलान्विताः ॥","lang":"sa","roman":"aśāstravihitaṃ ghoraṃ tapyante ye tapo janāḥ |\ndambhāhaṅkārasaṃyuktāḥ kāmarāgabalānvitāḥ ||","body":"The men who perform severe austerities, unenjoined by the Scriptures, wedded to vanity and egoism, impelled by the force of their desires and passions,","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","5 of 28"]]},"g2-17-5":{"route":"#/gitav/17.5","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:5:en2","title":"Gita 17.5, in another translation","body":"Those men who practise severe austerities not enjoined by the Shâstras, given to ostentation and egoism, possessed with the power of lust and attachment, torture, senseless as they are, all the organs in the body, and Me dwelling in the body within; know them to be of Asurika resolve.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","5 of 28"]]},"gv-17-6":{"route":"#/gitav/17.6","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:6:en","title":"Bhagavad Gita 17.6","text":"कर्षयन्तः शरीरस्थं भूतग्राममचेतसः ।\nमां चैवान्तःशरीरस्थं तान्विद्ध्यासुरनिश्चयान् ॥","lang":"sa","roman":"karṣayantaḥ śarīrasthaṃ bhūtagrāmamacetasaḥ |\nmāṃ caivāntaḥśarīrasthaṃ tānviddhyāsuraniścayān ||","body":"Unintelligent, tormenting the aggregated elements forming the body, and Me also, seated in the inner body, know these demoniacal in their resolves.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","6 of 28"]]},"gv-17-7":{"route":"#/gitav/17.7","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:7:en","title":"Bhagavad Gita 17.7","text":"आहारस्त्वपि सर्वस्य त्रिविधो भवति प्रियः ।\nयज्ञस्तपस्तथा दानं तेषां भेदमिमं शृणु ॥","lang":"sa","roman":"āhārastvapi sarvasya trividho bhavati priyaḥ |\nyajñastapastathā dānaṃ teṣāṃ bhedamimaṃ śṛṇu ||","body":"The food also which is dear to each is threefold, as also sacrifice, austerity and almsgiving. Hear thou the distinction of these.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","7 of 28"]]},"g2-17-7":{"route":"#/gitav/17.7","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:7:en2","title":"Gita 17.7, in another translation","body":"The food also which is liked by each of them is threefold, as also Yajna, austerity and almsgiving. Do thou hear this, their distinction.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","7 of 28"]]},"gv-17-8":{"route":"#/gitav/17.8","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:8:en","title":"Bhagavad Gita 17.8","text":"आयुःसत्त्वबलारोग्यसुखप्रीतिविवर्धनाः ।\nरस्याः स्निग्धाः स्थिरा हृद्या आहाराः सात्त्विकप्रियाः ॥","lang":"sa","roman":"āyuḥsattvabalārogyasukhaprītivivardhanāḥ |\nrasyāḥ snigdhāḥ sthirā hṛdyā āhārāḥ sāttvikapriyāḥ ||","body":"The foods that augment vitality, energy, vigour, health, joy and cheerfulness, delicious, bland, substantial and agreeable, are dear to the pure.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","8 of 28"]]},"g2-17-8":{"route":"#/gitav/17.8","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:8:en2","title":"Gita 17.8, in another translation","body":"The foods which augment vitality, energy, strength, health, cheerfulness and appetite, which are savoury and oleaginous, substantial and agreeable , are liked by the Sâttvika.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","8 of 28"]]},"gv-17-9":{"route":"#/gitav/17.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:9:en","title":"Bhagavad Gita 17.9","text":"कट्वम्ललवणात्युष्णतीक्ष्णरूक्षविदाहिनः ।\nआहारा राजसस्येष्टा दुःखशोकामयप्रदाः ॥","lang":"sa","roman":"kaṭvamlalavaṇātyuṣṇatīkṣṇarūkṣavidāhinaḥ |\nāhārā rājasasyeṣṭā duḥkhaśokāmayapradāḥ ||","body":"The passionate desire foods that are bitter, sour, saline, over-hot, pungent, dry and burning and which produce pain, grief and sickness.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","9 of 28"]]},"g2-17-9":{"route":"#/gitav/17.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:9:en2","title":"Gita 17.9, in another translation","body":"The foods that are bitter, sour, saline, excessively hot, pungent, dry and burning, are liked by the Râjasika, and are productive of pain, grief and disease.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","9 of 28"]]},"gv-17-10":{"route":"#/gitav/17.10","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:10:en","title":"Bhagavad Gita 17.10","text":"यातयामं गतरसं पूति पर्युषितं च यत् ।\nउच्छिष्टमपि चामेध्यं भोजनं तामसप्रियम् ॥","lang":"sa","roman":"yātayāmaṃ gatarasaṃ pūti paryuṣitaṃ ca yat |\nucchiṣṭamapi cāmedhyaṃ bhojanaṃ tāmasapriyam ||","body":"That which is stale and flat, putrid and corrupt, leavings also and unclean, is the food dear to the dark.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","10 of 28"]]},"g2-17-10":{"route":"#/gitav/17.10","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:10:en2","title":"Gita 17.10, in another translation","body":"That which is stale, tasteless, stinking, cooked overnight, refuse and impure, is the food liked by the Tâmasika. [","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","10 of 28"]]},"gv-17-11":{"route":"#/gitav/17.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:11:en","title":"Bhagavad Gita 17.11","text":"अफलाकाङ्क्षिभिर्यज्ञो विधिदृष्टो य इज्यते ।\nयष्टव्यमेवेति मनः समाधाय स सात्त्विकः ॥","lang":"sa","roman":"aphalākāṅkṣibhiryajño vidhidṛṣṭo ya ijyate |\nyaṣṭavyameveti manaḥ samādhāya sa sāttvikaḥ ||","body":"The sacrifice which is offered by men without desire for fruit, as enjoined by the ordinances, under the firm belief that sacrifice is a duty, that is pure.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","11 of 28"]]},"g2-17-11":{"route":"#/gitav/17.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:11:en2","title":"Gita 17.11, in another translation","body":"That Yajna is Sâttvika which is performed by men desiring no fruit, as enjoined by ordinance, with their mind fixed on the Yajna only, for its own sake.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","11 of 28"]]},"gv-17-12":{"route":"#/gitav/17.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:12:en","title":"Bhagavad Gita 17.12","text":"अभिसंधाय तु फलं दम्भार्थमपि चैव यत् ।\nइज्यते भरतश्रेष्ठ तं यज्ञं विद्धि राजसम् ॥","lang":"sa","roman":"abhisaṃdhāya tu phalaṃ dambhārthamapi caiva yat |\nijyate bharataśreṣṭha taṃ yajñaṃ viddhi rājasam ||","body":"The sacrifice offered with a view verily to fruit, and also indeed for self-glorification, O best of the Bhâratas; know thou that to be of passion.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","12 of 28"]]},"g2-17-12":{"route":"#/gitav/17.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:12:en2","title":"Gita 17.12, in another translation","body":"That which is performed, O best of the Bhâratas, seeking for fruit and for ostentation, know it to be a Râjasika Yajna.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","12 of 28"]]},"gv-17-13":{"route":"#/gitav/17.13","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:13:en","title":"Bhagavad Gita 17.13","text":"विधिहीनमसृष्टान्नं मन्त्रहीनमदक्षिणम् ।\nश्रद्धाविरहितं यज्ञं तामसं परिचक्षते ॥","lang":"sa","roman":"vidhihīnamasṛṣṭānnaṃ mantrahīnamadakṣiṇam |\nśraddhāvirahitaṃ yajñaṃ tāmasaṃ paricakṣate ||","body":"The sacrifice contrary to the ordinances, without distributing food, devoid of words of power and without gifts, empty of faith, is said to be of darkness.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","13 of 28"]]},"g2-17-13":{"route":"#/gitav/17.13","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:13:en2","title":"Gita 17.13, in another translation","body":"The Yajna performed without heed to ordinance, in which no food is distributed, which is devoid of Mantras, gifts, and Shraddhâ, is said to be Tâmasika.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","13 of 28"]]},"gv-17-14":{"route":"#/gitav/17.14","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:14:en","title":"Bhagavad Gita 17.14","text":"देवद्विजगुरुप्राज्ञपूजनं शौचमार्जवम् ।\nब्रह्मचर्यमहिंसा च शारीरं तप उच्यते ॥","lang":"sa","roman":"devadvijaguruprājñapūjanaṃ śaucamārjavam |\nbrahmacaryamahiṃsā ca śārīraṃ tapa ucyate ||","body":"Worship given to the Gods, to the twice-born, to the teachers and to the wise, purity, straightforwardness, continence and harmlessness, are called the austerity of the body.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","14 of 28"]]},"g2-17-14":{"route":"#/gitav/17.14","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:14:en2","title":"Gita 17.14, in another translation","body":"Worship of the Devas, the twice-born, the Gurus and the wise, purity, straightforwardness, continence, and non-injury are called the austerity of the body.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","14 of 28"]]},"gv-17-15":{"route":"#/gitav/17.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:15:en","title":"Bhagavad Gita 17.15","text":"अनुद्वेगकरं वाक्यं सत्यं प्रियहितं च यत् ।\nस्वाध्यायाभ्यसनं चैव वाङ्मयं तप उच्यते ॥","lang":"sa","roman":"anudvegakaraṃ vākyaṃ satyaṃ priyahitaṃ ca yat |\nsvādhyāyābhyasanaṃ caiva vāṅmayaṃ tapa ucyate ||","body":"Speech causing no annoyance, truthful, pleasant and beneficial, the practice of the study of the Scriptures, are called the austerity of speech.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","15 of 28"]]},"g2-17-15":{"route":"#/gitav/17.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:15:en2","title":"Gita 17.15, in another translation","body":"Speech which causes no vexation, and is true, as also agreeable and beneficial, and regular study of the Vedas,— these are said to form the austerity of speech.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","15 of 28"]]},"gv-17-16":{"route":"#/gitav/17.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:16:en","title":"Bhagavad Gita 17.16","text":"मनःप्रसादः सौम्यत्वं मौनमात्मविनिग्रहः ।\nभावसंशुद्धिरित्येतत्तपो मानसमुच्यते ॥","lang":"sa","roman":"manaḥprasādaḥ saumyatvaṃ maunamātmavinigrahaḥ |\nbhāvasaṃśuddhirityetattapo mānasamucyate ||","body":"Mental happiness, equilibrium, silence, self-control, purity of nature—these are called the austerity of the mind.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","16 of 28"]]},"g2-17-16":{"route":"#/gitav/17.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:16:en2","title":"Gita 17.16, in another translation","body":"Serenity of mind, kindliness, silence, self-control, honesty of motive,—this is called the mental austerity.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","16 of 28"]]},"gv-17-17":{"route":"#/gitav/17.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:17:en","title":"Bhagavad Gita 17.17","text":"श्रद्धया परया तप्तं तपस्तत्त्रिविधं नरैः ।\nअफलाकाङ्क्षिभिर्युक्तैः सात्त्विकं परिचक्षते ॥","lang":"sa","roman":"śraddhayā parayā taptaṃ tapastattrividhaṃ naraiḥ |\naphalākāṅkṣibhiryuktaiḥ sāttvikaṃ paricakṣate ||","body":"This threefold austerity, performed by men with the utmost faith, without desire for fruit, harmonised, is said to be pure.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","17 of 28"]]},"g2-17-17":{"route":"#/gitav/17.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:17:en2","title":"Gita 17.17, in another translation","body":"This threefold austerity practised by steadfast men, with great Shraddhâ, desiring no fruit, is said to be Sâttvika.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","17 of 28"]]},"gv-17-18":{"route":"#/gitav/17.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:18:en","title":"Bhagavad Gita 17.18","text":"सत्कारमानपूजार्थं तपो दम्भेन चैव यत् ।\nक्रियते तदिह प्रोक्तं राजसं चलमध्रुवम् ॥","lang":"sa","roman":"satkāramānapūjārthaṃ tapo dambhena caiva yat |\nkriyate tadiha proktaṃ rājasaṃ calamadhruvam ||","body":"The austerity which is practised with the object of gaining respect, honour and worship, and for ostentation, is said to be of passion, unstable and fleeting.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","18 of 28"]]},"g2-17-18":{"route":"#/gitav/17.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:18:en2","title":"Gita 17.18, in another translation","body":"That austerity which is practised with the object of gaining welcome, honour and worship, and with ostentation, is here said to be Râjasika, unstable and transitory.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","18 of 28"]]},"gv-17-19":{"route":"#/gitav/17.19","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:19:en","title":"Bhagavad Gita 17.19","text":"मूढग्राहेणात्मनो यत्पीडया क्रियते तपः ।\nपरस्योत्सादनार्थं वा तत्तामसमुदाहृतम् ॥","lang":"sa","roman":"mūḍhagrāheṇātmano yatpīḍayā kriyate tapaḥ |\nparasyotsādanārthaṃ vā tattāmasamudāhṛtam ||","body":"That austerity done under a deluded understanding, with self-torture, or with the object of destroying another, that is declared of darkness.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","19 of 28"]]},"g2-17-19":{"route":"#/gitav/17.19","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:19:en2","title":"Gita 17.19, in another translation","body":"That austerity which is practised out of a foolish notion, with self-torture or for the purpose of wining another, is declared to be Tâmasika.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","19 of 28"]]},"gv-17-20":{"route":"#/gitav/17.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:20:en","title":"Bhagavad Gita 17.20","text":"दातव्यमिति यद्दानं दीयतेऽनुपकारिणे ।\nदेशे काले च पात्रे च तद्दानं सात्त्विकं स्मृतम् ॥","lang":"sa","roman":"dātavyamiti yaddānaṃ dīyate’nupakāriṇe |\ndeśe kāle ca pātre ca taddānaṃ sāttvikaṃ smṛtam ||","body":"That alms given to one who does nothing in return, believing that a gift ought to be made in a fit place and time to a worthy person, that alms is accounted pure.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","20 of 28"]]},"g2-17-20":{"route":"#/gitav/17.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:20:en2","title":"Gita 17.20, in another translation","body":"To give is right, gift given with this idea, to one who does no service in return, in a fit place and to a worthy person, that gift is held to be Sâttvika.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","20 of 28"]]},"gv-17-21":{"route":"#/gitav/17.21","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:21:en","title":"Bhagavad Gita 17.21","text":"यत्तु प्रत्युपकारार्थं फलमुद्दिश्य वा पुनः ।\nदीयते च परिक्लिष्टं तद्दानं राजसं स्मृतम् ॥","lang":"sa","roman":"yattu pratyupakārārthaṃ phalamuddiśya vā punaḥ |\ndīyate ca parikliṣṭaṃ taddānaṃ rājasaṃ smṛtam ||","body":"That given with a view to receiving in return, or looking for fruit again, or grudgingly, that alms is accounted of passion.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","21 of 28"]]},"g2-17-21":{"route":"#/gitav/17.21","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:21:en2","title":"Gita 17.21, in another translation","body":"And what is given with a view to receiving in return, or looking for the fruit, or again reluctantly, that gift is held to be Râjasika.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","21 of 28"]]},"gv-17-22":{"route":"#/gitav/17.22","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:22:en","title":"Bhagavad Gita 17.22","text":"अदेशकाले यद्दानमपात्रेभ्यश्च दीयते ।\nअसत्कृतमवज्ञातं तत्तामसमुदाहृतम् ॥","lang":"sa","roman":"adeśakāle yaddānamapātrebhyaśca dīyate |\nasatkṛtamavajñātaṃ tattāmasamudāhṛtam ||","body":"That alms given at unfit place and time, and to unworthy persons, disrespectfully and contemptuously, that is declared of darkness.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","22 of 28"]]},"g2-17-22":{"route":"#/gitav/17.22","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:22:en2","title":"Gita 17.22, in another translation","body":"The gift that is given at the wrong place or time, to unworthy persons, without regard or with disdain, that is declared to be Tâmasika.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","22 of 28"]]},"gv-17-23":{"route":"#/gitav/17.23","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:23:en","title":"Bhagavad Gita 17.23","text":"ॐतत्सदिति निर्देशो ब्रह्मणस्त्रिविधः स्मृतः ।\nब्राह्मणास्तेन वेदाश्च यज्ञाश्च विहिताः पुरा ॥","lang":"sa","roman":"oṃtatsaditi nirdeśo brahmaṇastrividhaḥ smṛtaḥ |\nbrāhmaṇāstena vedāśca yajñāśca vihitāḥ purā ||","body":"\" Aum Tat Sat,\" this has been considered to be the threefold designation of the Eternal. By that were ordained of old Brâhmanas, Vedas and sacrifices.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","23 of 28"]]},"g2-17-23":{"route":"#/gitav/17.23","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:23:en2","title":"Gita 17.23, in another translation","body":"\"Om, Tat, Sat\": this has been declared to be the triple designation of Brahman. By that were made of old the Brâhmanas, the Vedas and the Yajnas.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","23 of 28"]]},"gv-17-24":{"route":"#/gitav/17.24","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:24:en","title":"Bhagavad Gita 17.24","text":"तस्मादोमित्युदाहृत्य यज्ञदानतपःक्रियाः ।\nप्रवर्तन्ते विधानोक्ताः सततं ब्रह्मवादिनाम् ॥","lang":"sa","roman":"tasmādomityudāhṛtya yajñadānatapaḥkriyāḥ |\npravartante vidhānoktāḥ satataṃ brahmavādinām ||","body":"Therefore with the pronunciation of \" Aum \" the acts of sacrifice, gift and austerity as laid down in the ordinances are always commenced by the knowers of the Eternal.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","24 of 28"]]},"g2-17-24":{"route":"#/gitav/17.24","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:24:en2","title":"Gita 17.24, in another translation","body":"Therefore, uttering 'Om,' are the acts of sacrifice, gift and austerity as enjoined in the ordinances, always begun by the followers of the Vedas.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","24 of 28"]]},"gv-17-25":{"route":"#/gitav/17.25","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:25:en","title":"Bhagavad Gita 17.25","text":"तदित्यनभिसन्धाय फलं यज्ञतपःक्रियाः ।\nदानक्रियाश्च विविधाः क्रियन्ते मोक्षकाङ्क्षिभिः ॥","lang":"sa","roman":"tadityanabhisandhāya phalaṃ yajñatapaḥkriyāḥ |\ndānakriyāśca vividhāḥ kriyante mokṣakāṅkṣibhiḥ ||","body":"With the pronunciation of \" Tat \" and without aiming at fruit are performed the various acts of sacrifice, austerity and gift, by those desiring liberation.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","25 of 28"]]},"g2-17-25":{"route":"#/gitav/17.25","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:25:en2","title":"Gita 17.25, in another translation","body":"Uttering Tat, without aiming at fruits, are the various acts of Yajna, austerity and gift performed by the seekers of Moksha.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","25 of 28"]]},"gv-17-26":{"route":"#/gitav/17.26","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:26:en","title":"Bhagavad Gita 17.26","text":"सद्भावे साधुभावे च सदित्येतत्प्रयुज्यते ।\nप्रशस्ते कर्मणि तथा सच्छब्दः पार्थ युज्यते ॥","lang":"sa","roman":"sadbhāve sādhubhāve ca sadityetatprayujyate |\npraśaste karmaṇi tathā sacchabdaḥ pārtha yujyate ||","body":"\" Sat \" is used in the sense of reality and goodness; likewise, O Pârtha, the word \" Sat \" is used in the sense of a good work.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","26 of 28"]]},"g2-17-26":{"route":"#/gitav/17.26","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:26:en2","title":"Gita 17.26, in another translation","body":"The word Sat is used in the sense of reality and of goodness; and so also, Pârtha, the word Sat is used in the sense of an auspicious act.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","26 of 28"]]},"gv-17-27":{"route":"#/gitav/17.27","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:27:en","title":"Bhagavad Gita 17.27","text":"यज्ञे तपसि दाने च स्थितिः सदिति चोच्यते ।\nकर्म चैव तदर्थीयं सदित्येवाभिधीयते ॥","lang":"sa","roman":"yajñe tapasi dāne ca sthitiḥ saditi cocyate |\nkarma caiva tadarthīyaṃ sadityevābhidhīyate ||","body":"Steadfastness in sacrifice, austerity and gift is also called \" Sat \", and action for the sake of the Supreme is also named \" Sat.\"","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","27 of 28"]]},"g2-17-27":{"route":"#/gitav/17.27","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:27:en2","title":"Gita 17.27, in another translation","body":"Steadiness in Yajna, austerity and gift is also called 'Sat': as also action in connection with these (or, action for the sake of the Lord) is called Sat.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","27 of 28"]]},"gv-17-28":{"route":"#/gitav/17.28","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:28:en","title":"Bhagavad Gita 17.28","text":"अश्रद्धया हुतं दत्तं तपस्तप्तं कृतं च यत् ।\nअसदित्युच्यते पार्थ न च तत्प्रेत्य नो इह ॥","lang":"sa","roman":"aśraddhayā hutaṃ dattaṃ tapastaptaṃ kṛtaṃ ca yat |\nasadityucyate pārtha na ca tatpretya no iha ||","body":"Whatsoever is wrought without faith, oblation, gift, austerity, or other deed, \"Asat\" it is called, O Pârtha; it is nought, here or hereafter.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","28 of 28"]]},"g2-17-28":{"route":"#/gitav/17.28","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 17 — The Enquiry into the Threefold Shraddha","src":"gita:17:28:en2","title":"Gita 17.28, in another translation","body":"Whatever is sacrificed, given or performed, and whatever austerity is practised without Shraddhâ, it is called Asat, O Pârtha; it is naught here or hereafter.","facts":[["Chapter","The Enquiry into the Threefold Shraddha"],["Verse","28 of 28"]]},"gv-18-1":{"route":"#/gitav/18.1","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:1:en","title":"Bhagavad Gita 18.1","text":"संन्यासस्य महाबाहो तत्त्वमिच्छामि वेदितुम् ।\nत्यागस्य च हृषीकेश पृथक्केशिनिषूदन ॥","lang":"sa","roman":"saṃnyāsasya mahābāho tattvamicchāmi veditum |\ntyāgasya ca hṛṣīkeśa pṛthakkeśiniṣūdana ||","body":"Arjuna said: I desire, O mighty-armed, to know severally the essence of renunciation, O Hrishîkesha, and of relinquishment, O Keshinishûdana.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","1 of 78"]]},"g2-18-1":{"route":"#/gitav/18.1","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:1:en2","title":"Gita 18.1, in another translation","body":"I desire to know severally, O mighty-armed, the truth of Sannyâsa, O Hrishikesha, as also of Tyâga, O slayer of Keshi.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","1 of 78"]]},"gv-18-2":{"route":"#/gitav/18.2","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:2:en","title":"Bhagavad Gita 18.2","text":"काम्यानां कर्मणां न्यासं संन्यासं कवयो विदुः ।\nसर्वकर्मफलत्यागं प्राहुस्त्यागं विचक्षणाः ॥","lang":"sa","roman":"kāmyānāṃ karmaṇāṃ nyāsaṃ saṃnyāsaṃ kavayo viduḥ |\nsarvakarmaphalatyāgaṃ prāhustyāgaṃ vicakṣaṇāḥ ||","body":"The Blessed Lord said: Sages have known as renunciation the renouncing of works with desire; the relinquishing of the fruit of all actions is called relinquishment by the wise.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","2 of 78"]]},"g2-18-2":{"route":"#/gitav/18.2","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:2:en2","title":"Gita 18.2, in another translation","body":"The renunciation of Kâmya actions, the sages understand as. Sannyâsa: the wise declare the abandonment of the fruits of all works as Tyâga.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","2 of 78"]]},"gv-18-3":{"route":"#/gitav/18.3","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:3:en","title":"Bhagavad Gita 18.3","text":"त्याज्यं दोषवदित्येके कर्म प्राहुर्मनीषिणः ।\nयज्ञदानतपःकर्म न त्याज्यमिति चापरे ॥","lang":"sa","roman":"tyājyaṃ doṣavadityeke karma prāhurmanīṣiṇaḥ |\nyajñadānatapaḥkarma na tyājyamiti cāpare ||","body":"\"Action should be relinquished as an evil,\" declare some thoughtful men; \"acts of sacrifice, gift and austerity should not be relinquished,\" say others.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","3 of 78"]]},"g2-18-3":{"route":"#/gitav/18.3","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:3:en2","title":"Gita 18.3, in another translation","body":"Some philosophers declare that all action should be relinquished as an evil, whilst others (say) that the work of Yajna, gift and austerity should not be relinquished.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","3 of 78"]]},"gv-18-4":{"route":"#/gitav/18.4","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:4:en","title":"Bhagavad Gita 18.4","text":"निश्चयं शृणु मे तत्र त्यागे भरतसत्तम ।\nत्यागो हि पुरुषव्याघ्र त्रिविधः सम्प्रकीर्तितः ॥","lang":"sa","roman":"niścayaṃ śṛṇu me tatra tyāge bharatasattama |\ntyāgo hi puruṣavyāghra trividhaḥ samprakīrtitaḥ ||","body":"Hear my conclusions as to that relinquishment, O best of the Bhâratas; since relinquishment, O tiger of men, has been explained as threefold.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","4 of 78"]]},"g2-18-4":{"route":"#/gitav/18.4","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:4:en2","title":"Gita 18.4, in another translation","body":"Hear from Me the final truth about relinquishment, O best of the Bhâratas. For relinquishment has been declared to be of three kinds, O tiger among men.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","4 of 78"]]},"gv-18-5":{"route":"#/gitav/18.5","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:5:en","title":"Bhagavad Gita 18.5","text":"यज्ञदानतपःकर्म न त्याज्यं कार्यमेव तत् ।\nयज्ञो दानं तपश्चैव पावनानि मनीषिणाम् ॥","lang":"sa","roman":"yajñadānatapaḥkarma na tyājyaṃ kāryameva tat |\nyajño dānaṃ tapaścaiva pāvanāni manīṣiṇām ||","body":"Acts of sacrifice, gift and austerity should not be relinquished, but should be performed; sacrifice, gift and also austerity are the purifiers of the intelligent.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","5 of 78"]]},"g2-18-5":{"route":"#/gitav/18.5","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:5:en2","title":"Gita 18.5, in another translation","body":"The work of Yajna, gift and austerity should not be relinquished, but it should indeed be performed; (for) Yajna, gift and austerity are purifying to the wise.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","5 of 78"]]},"gv-18-6":{"route":"#/gitav/18.6","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:6:en","title":"Bhagavad Gita 18.6","text":"एतान्यपि तु कर्माणि सङ्गं त्यक्त्वा फलानि च ।\nकर्तव्यानीति मे पार्थ निश्चितं मतमुत्तमम् ॥","lang":"sa","roman":"etānyapi tu karmāṇi saṅgaṃ tyaktvā phalāni ca |\nkartavyānīti me pārtha niścitaṃ matamuttamam ||","body":"But even these actions should be done leaving aside attachment and fruit, O Pârtha; that is my certain and best belief.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","6 of 78"]]},"g2-18-6":{"route":"#/gitav/18.6","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:6:en2","title":"Gita 18.6, in another translation","body":"But even these works, O Pârtha, should be performed, leaving attachment and the fruits;—such is My best and certain conviction.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","6 of 78"]]},"gv-18-7":{"route":"#/gitav/18.7","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:7:en","title":"Bhagavad Gita 18.7","text":"नियतस्य तु संन्यासः कर्मणो नोपपद्यते ।\nमोहात्तस्य परित्यागस्तामसः परिकीर्तितः ॥","lang":"sa","roman":"niyatasya tu saṃnyāsaḥ karmaṇo nopapadyate |\nmohāttasya parityāgastāmasaḥ parikīrtitaḥ ||","body":"Verily renunciation of actions that are prescribed is not proper; the relinquishment thereof from delusion is said to be of darkness.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","7 of 78"]]},"g2-18-7":{"route":"#/gitav/18.7","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:7:en2","title":"Gita 18.7, in another translation","body":"But the renunciation of obligatory action is not proper. Abandonment of the same from delusion is declared to be Tâmasika.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","7 of 78"]]},"gv-18-8":{"route":"#/gitav/18.8","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:8:en","title":"Bhagavad Gita 18.8","text":"दुःखमित्येव यत्कर्म कायक्लेशभयात्त्यजेत् ।\nस कृत्वा राजसं त्यागं नैव त्यागफलं लभेत् ॥","lang":"sa","roman":"duḥkhamityeva yatkarma kāyakleśabhayāttyajet |\nsa kṛtvā rājasaṃ tyāgaṃ naiva tyāgaphalaṃ labhet ||","body":"He who relinquisheth an action from fear of physical suffering, saying \"Painful,\" thus performing a passionate relinquishment, obtaineth not the fruit of relinquishment.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","8 of 78"]]},"g2-18-8":{"route":"#/gitav/18.8","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:8:en2","title":"Gita 18.8, in another translation","body":"He who from fear of bodily trouble relinquishes action, because it is painful, thus performing a Râjasika relinquishment, he obtains not the fruit thereof.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","8 of 78"]]},"gv-18-9":{"route":"#/gitav/18.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:9:en","title":"Bhagavad Gita 18.9","text":"कार्यमित्येव यत्कर्म नियतं क्रियतेऽर्जुन ।\nसङ्गं त्यक्त्वा फलं चैव स त्यागः सात्त्विको मतः ॥","lang":"sa","roman":"kāryamityeva yatkarma niyataṃ kriyate’rjuna |\nsaṅgaṃ tyaktvā phalaṃ caiva sa tyāgaḥ sāttviko mataḥ ||","body":"He who performeth a prescribed action, saying, \"it ought to be done,\" O Arjuna, relinquishing attachment and also fruit, that relinquishment is regarded as pure.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","9 of 78"]]},"g2-18-9":{"route":"#/gitav/18.9","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:9:en2","title":"Gita 18.9, in another translation","body":"When obligatory work is performed, O Arjuna, only because it ought to be done, leaving attachment and fruit, such relinquishment is regarded as Sâttvika.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","9 of 78"]]},"gv-18-10":{"route":"#/gitav/18.10","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:10:en","title":"Bhagavad Gita 18.10","text":"न द्वेष्ट्यकुशलं कर्म कुशले नानुषज्जते ।\nत्यागी सत्त्वसमाविष्टो मेधावी छिन्नसंशयः ॥","lang":"sa","roman":"na dveṣṭyakuśalaṃ karma kuśale nānuṣajjate |\ntyāgī sattvasamāviṣṭo medhāvī chinnasaṃśayaḥ ||","body":"The relinquisher pervaded by purity, intelligent and with doubts cut away, hateth not unpleasurable action nor is attached to pleasurable.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","10 of 78"]]},"g2-18-10":{"route":"#/gitav/18.10","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:10:en2","title":"Gita 18.10, in another translation","body":"The relinquisher endued with Sattva and a steady understanding and with his doubts dispelled, hates not a disagreeable work nor is attached to an agreeable one.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","10 of 78"]]},"gv-18-11":{"route":"#/gitav/18.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:11:en","title":"Bhagavad Gita 18.11","text":"न हि देहभृता शक्यं त्यक्तुं कर्माण्यशेषतः ।\nयस्तु कर्मफलत्यागी स त्यागीत्यभिधीयते ॥","lang":"sa","roman":"na hi dehabhṛtā śakyaṃ tyaktuṃ karmāṇyaśeṣataḥ |\nyastu karmaphalatyāgī sa tyāgītyabhidhīyate ||","body":"Nor indeed can embodied beings completely relinquish action; verily he who relinquisheth the fruit of action, he is said to be a relinquisher.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","11 of 78"]]},"g2-18-11":{"route":"#/gitav/18.11","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:11:en2","title":"Gita 18.11, in another translation","body":"Actions cannot be entirely relinquished by an embodied being, but he who relinquishes the fruits of action is called a relinquisher.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","11 of 78"]]},"gv-18-12":{"route":"#/gitav/18.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:12:en","title":"Bhagavad Gita 18.12","text":"अनिष्टमिष्टं मिश्रं च त्रिविधं कर्मणः फलम् ।\nभवत्यत्यागिनां प्रेत्य न तु संन्यासिनां क्वचित् ॥","lang":"sa","roman":"aniṣṭamiṣṭaṃ miśraṃ ca trividhaṃ karmaṇaḥ phalam |\nbhavatyatyāgināṃ pretya na tu saṃnyāsināṃ kvacit ||","body":"Good, evil and mixed—threefold is the fruit of action hereafter for the non-relinquisher; but there is none ever for the renouncer.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","12 of 78"]]},"g2-18-12":{"route":"#/gitav/18.12","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:12:en2","title":"Gita 18.12, in another translation","body":"The threefold fruit of action—disagreeable, agreeable and mixed,—accrues to non-relinquishers after death, but never to relinquishers.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","12 of 78"]]},"gv-18-13":{"route":"#/gitav/18.13","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:13:en","title":"Bhagavad Gita 18.13","text":"पञ्चैतानि महाबाहो कारणानि निबोध मे ।\nसांख्ये कृतान्ते प्रोक्तानि सिद्धये सर्वकर्मणाम् ॥","lang":"sa","roman":"pañcaitāni mahābāho kāraṇāni nibodha me |\nsāṃkhye kṛtānte proktāni siddhaye sarvakarmaṇām ||","body":"These five causes, O mighty-armed, learn of Me as declared in the Sâñkhya system for the accomplishment of all actions:","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","13 of 78"]]},"g2-18-13":{"route":"#/gitav/18.13","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:13:en2","title":"Gita 18.13, in another translation","body":"Learn from Me, O mighty-armed, these five causes for the accomplishment of all works as declared in the wisdom which is the end of all action:","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","13 of 78"]]},"gv-18-14":{"route":"#/gitav/18.14","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:14:en","title":"Bhagavad Gita 18.14","text":"अधिष्ठानं तथा कर्ता करणं च पृथग्विधम् ।\nविविधाश्च पृथक्चेष्टा दैवं चैवात्र पञ्चमम् ॥","lang":"sa","roman":"adhiṣṭhānaṃ tathā kartā karaṇaṃ ca pṛthagvidham |\nvividhāśca pṛthakceṣṭā daivaṃ caivātra pañcamam ||","body":"The body, the actor, the various organs, the diverse kinds of energies, and the presiding deities also, the fifth.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","14 of 78"]]},"g2-18-14":{"route":"#/gitav/18.14","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:14:en2","title":"Gita 18.14, in another translation","body":"The body, the agent, the various senses, the different functions of a manifold kind, and the presiding divinity, the fifth of these;","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","14 of 78"]]},"gv-18-15":{"route":"#/gitav/18.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:15:en","title":"Bhagavad Gita 18.15","text":"शरीरवाङ्मनोभिर्यत्कर्म प्रारभते नरः ।\nन्याय्यं वा विपरीतं वा पञ्चैते तस्य हेतवः ॥","lang":"sa","roman":"śarīravāṅmanobhiryatkarma prārabhate naraḥ |\nnyāyyaṃ vā viparītaṃ vā pañcaite tasya hetavaḥ ||","body":"Whatever action a man performeth by his body, speech and mind, whether right or the reverse, these five are the cause thereof.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","15 of 78"]]},"g2-18-15":{"route":"#/gitav/18.15","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:15:en2","title":"Gita 18.15, in another translation","body":"Whatever action a man performs by his body, speech and mind—whether right or the reverse—these five are its causes.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","15 of 78"]]},"gv-18-16":{"route":"#/gitav/18.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:16:en","title":"Bhagavad Gita 18.16","text":"तत्रैवं सति कर्तारमात्मानं केवलं तु यः ।\nपश्यत्यकृतबुद्धित्वान्न स पश्यति दुर्मतिः ॥","lang":"sa","roman":"tatraivaṃ sati kartāramātmānaṃ kevalaṃ tu yaḥ |\npaśyatyakṛtabuddhitvānna sa paśyati durmatiḥ ||","body":"That being so, he verily who—owing to untrained Reason—looketh on his Self, which is isolated, as the actor, he of perverted intelligence, seeth not.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","16 of 78"]]},"g2-18-16":{"route":"#/gitav/18.16","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:16:en2","title":"Gita 18.16, in another translation","body":"Such being the case, he who through a non-purified understanding looks upon his Self, the Absolute, as the agent, he of perverted mind sees not.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","16 of 78"]]},"gv-18-17":{"route":"#/gitav/18.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:17:en","title":"Bhagavad Gita 18.17","text":"यस्य नाहंकृतो भावो बुद्धिर्यस्य न लिप्यते ।\nहत्वापि स इमाँल्लोकान्न हन्ति न निबध्यते ॥","lang":"sa","roman":"yasya nāhaṃkṛto bhāvo buddhiryasya na lipyate |\nhatvāpi sa imām̐llokānna hanti na nibadhyate ||","body":"He who is free from the egoistic notion, whose Reason is not affected, though he slay these peoples, he slayeth not, nor is bound.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","17 of 78"]]},"g2-18-17":{"route":"#/gitav/18.17","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:17:en2","title":"Gita 18.17, in another translation","body":"He who is free from the notion of egoism, whose intelligence is not affected (by good or evil), though he kills these people, he kills not, nor is bound (by the action);","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","17 of 78"]]},"gv-18-18":{"route":"#/gitav/18.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:18:en","title":"Bhagavad Gita 18.18","text":"ज्ञानं ज्ञेयं परिज्ञाता त्रिविधा कर्मचोदना ।\nकरणं कर्म कर्तेति त्रिविधः कर्मसंग्रहः ॥","lang":"sa","roman":"jñānaṃ jñeyaṃ parijñātā trividhā karmacodanā |\nkaraṇaṃ karma karteti trividhaḥ karmasaṃgrahaḥ ||","body":"Knowledge, the knowable and the knower, the threefold impulse to action; the organ, the action, the actor, the threefold constituents of action.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","18 of 78"]]},"g2-18-18":{"route":"#/gitav/18.18","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:18:en2","title":"Gita 18.18, in another translation","body":"Knowledge, the known and the knower form the threefold cause of action. The instrument, the object and the agent are the threefold basis of action.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","18 of 78"]]},"gv-18-19":{"route":"#/gitav/18.19","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:19:en","title":"Bhagavad Gita 18.19","text":"ज्ञानं कर्म च कर्ता च त्रिधैव गुणभेदतः ।\nप्रोच्यते गुणसंख्याने यथावच्छृणु तान्यपि ॥","lang":"sa","roman":"jñānaṃ karma ca kartā ca tridhaiva guṇabhedataḥ |\nprocyate guṇasaṃkhyāne yathāvacchṛṇu tānyapi ||","body":"Knowledge, action and actor in the category of qualities are also said to be severally threefold, from the difference of qualities; hear thou duly these also.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","19 of 78"]]},"g2-18-19":{"route":"#/gitav/18.19","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:19:en2","title":"Gita 18.19, in another translation","body":"Knowledge, action and agent are declared in the Sânkhya philosophy to be of three kinds only, from the distinction of Gunas: hear them also duly.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","19 of 78"]]},"gv-18-20":{"route":"#/gitav/18.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:20:en","title":"Bhagavad Gita 18.20","text":"सर्वभूतेषु येनैकं भावमव्ययमीक्षते ।\nअविभक्तं विभक्तेषु तज्ज्ञानं विद्धि सात्त्विकम् ॥","lang":"sa","roman":"sarvabhūteṣu yenaikaṃ bhāvamavyayamīkṣate |\navibhaktaṃ vibhakteṣu tajjñānaṃ viddhi sāttvikam ||","body":"That by which one indestructible Being is seen in all beings, inseparate in the separated, know thou that knowledge as pure.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","20 of 78"]]},"g2-18-20":{"route":"#/gitav/18.20","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:20:en2","title":"Gita 18.20, in another translation","body":"That by which the one indestructible Substance is seen in all beings, inseparate in the separated, know that knowledge to be Sâttvika.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","20 of 78"]]},"gv-18-21":{"route":"#/gitav/18.21","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:21:en","title":"Bhagavad Gita 18.21","text":"पृथक्त्वेन तु यज्ज्ञानं नानाभावान्पृथग्विधान् ।\nवेत्ति सर्वेषु भूतेषु तज्ज्ञानं विद्धि राजसम् ॥","lang":"sa","roman":"pṛthaktvena tu yajjñānaṃ nānābhāvānpṛthagvidhān |\nvetti sarveṣu bhūteṣu tajjñānaṃ viddhi rājasam ||","body":"But that knowledge which regardeth the several manifold existences in all beings as separate, that knowledge know thou as of passion;","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","21 of 78"]]},"g2-18-21":{"route":"#/gitav/18.21","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:21:en2","title":"Gita 18.21, in another translation","body":"But that knowledge which sees in all beings various entities of distinct kinds as different from one another, know thou that knowledge as Râjasika.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","21 of 78"]]},"gv-18-22":{"route":"#/gitav/18.22","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:22:en","title":"Bhagavad Gita 18.22","text":"यत्तु कृत्स्नवदेकस्मिन्कार्ये सक्तमहैतुकम् ।\nअतत्त्वार्थवदल्पं च तत्तामसमुदाहृतम् ॥","lang":"sa","roman":"yattu kṛtsnavadekasminkārye saktamahaitukam |\natattvārthavadalpaṃ ca tattāmasamudāhṛtam ||","body":"While that which clingeth to each one thing as if it were the whole, without reason, without grasping the reality, narrow, that is declared to be dark.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","22 of 78"]]},"g2-18-22":{"route":"#/gitav/18.22","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:22:en2","title":"Gita 18.22, in another translation","body":"Whilst that which is confined to one single effect as if it were the whole, without reason, without foundation in truth, and trivial,—that is declared to be Tâmasika.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","22 of 78"]]},"gv-18-23":{"route":"#/gitav/18.23","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:23:en","title":"Bhagavad Gita 18.23","text":"नियतं सङ्गरहितमरागद्वेषतः कृतम् ।\nअफलप्रेप्सुना कर्म यत्तत्सात्त्विकमुच्यते ॥","lang":"sa","roman":"niyataṃ saṅgarahitamarāgadveṣataḥ kṛtam |\naphalaprepsunā karma yattatsāttvikamucyate ||","body":"An action which is ordained, done by one undesirous of fruit, devoid of attachment, without love or hate, that is called pure.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","23 of 78"]]},"g2-18-23":{"route":"#/gitav/18.23","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:23:en2","title":"Gita 18.23, in another translation","body":"An ordained action done without love or hatred by one not desirous of the fruit and free from attachment, is declared to be Sâttvika.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","23 of 78"]]},"gv-18-24":{"route":"#/gitav/18.24","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:24:en","title":"Bhagavad Gita 18.24","text":"यत्तु कामेप्सुना कर्म साहङ्कारेण वा पुनः ।\nक्रियते बहुलायासं तद्राजसमुदाहृतम् ॥","lang":"sa","roman":"yattu kāmepsunā karma sāhaṅkāreṇa vā punaḥ |\nkriyate bahulāyāsaṃ tadrājasamudāhṛtam ||","body":"But that action that is done by one longing for desires, or again with egoism, or with much effort, that is declared to be passionate.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","24 of 78"]]},"g2-18-24":{"route":"#/gitav/18.24","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:24:en2","title":"Gita 18.24, in another translation","body":"But the action which is performed desiring desires, or with self-conceit and with much effort, is declared to be Râjasika.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","24 of 78"]]},"gv-18-25":{"route":"#/gitav/18.25","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:25:en","title":"Bhagavad Gita 18.25","text":"अनुबन्धं क्षयं हिंसामनपेक्ष्य च पौरुषम् ।\nमोहादारभ्यते कर्म यत्तत्तामसमुच्यते ॥","lang":"sa","roman":"anubandhaṃ kṣayaṃ hiṃsāmanapekṣya ca pauruṣam |\nmohādārabhyate karma yattattāmasamucyate ||","body":"The action undertaken from delusion, without regard to capacity and consequences—loss and injury to others—that is declared to be dark.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","25 of 78"]]},"g2-18-25":{"route":"#/gitav/18.25","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:25:en2","title":"Gita 18.25, in another translation","body":"That action is declared to be Tâmasika which is undertaken through delusion, without heed to the consequence, loss (of power and wealth), injury (to others) and (one's own) ability.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","25 of 78"]]},"gv-18-26":{"route":"#/gitav/18.26","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:26:en","title":"Bhagavad Gita 18.26","text":"मुक्तसङ्गोऽनहंवादी धृत्युत्साहसमन्वितः ।\nसिद्ध्यसिद्ध्योर्निर्विकारः कर्ता सात्त्विक उच्यते ॥","lang":"sa","roman":"muktasaṅgo’nahaṃvādī dhṛtyutsāhasamanvitaḥ |\nsiddhyasiddhyornirvikāraḥ kartā sāttvika ucyate ||","body":"Liberated from attachment, not egoistic, endued with firmness and confidence, unchanged by success or failure, that actor is called pure.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","26 of 78"]]},"g2-18-26":{"route":"#/gitav/18.26","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:26:en2","title":"Gita 18.26, in another translation","body":"An agent who is free from attachment, non-egotistic, endued with fortitude and enthusiasm and unaffected in success or failure, is called Sâttvika.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","26 of 78"]]},"gv-18-27":{"route":"#/gitav/18.27","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:27:en","title":"Bhagavad Gita 18.27","text":"रागी कर्मफलप्रेप्सुर्लुब्धो हिंसात्मकोऽशुचिः ।\nहर्षशोकान्वितः कर्ता राजसः परिकीर्तितः ॥","lang":"sa","roman":"rāgī karmaphalaprepsurlubdho hiṃsātmako’śuciḥ |\nharṣaśokānvitaḥ kartā rājasaḥ parikīrtitaḥ ||","body":"Impassioned, desiring to obtain the fruit of actions, greedy, harmful, impure, moved by joy and sorrow, such an actor is pronounced passionate.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","27 of 78"]]},"g2-18-27":{"route":"#/gitav/18.27","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:27:en2","title":"Gita 18.27, in another translation","body":"He who is passionate, desirous of the fruits of action, greedy, malignant, impure, easily elated or dejected, such an agent is called Râjasika.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","27 of 78"]]},"gv-18-28":{"route":"#/gitav/18.28","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:28:en","title":"Bhagavad Gita 18.28","text":"अयुक्तः प्राकृतः स्तब्धः शठो नैष्कृतिकोऽलसः ।\nविषादी दीर्घसूत्री च कर्ता तामस उच्यते ॥","lang":"sa","roman":"ayuktaḥ prākṛtaḥ stabdhaḥ śaṭho naiṣkṛtiko’lasaḥ |\nviṣādī dīrghasūtrī ca kartā tāmasa ucyate ||","body":"Discordant, vulgar, stubborn, cheating, malicious, indolent, despairful, procrastinating, that actor is called dark.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","28 of 78"]]},"g2-18-28":{"route":"#/gitav/18.28","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:28:en2","title":"Gita 18.28, in another translation","body":"Unsteady, vulgar, arrogant, dishonest, malicious, indolent, desponding and procrastinating, such an agent is called Tâmasika.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","28 of 78"]]},"gv-18-29":{"route":"#/gitav/18.29","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:29:en","title":"Bhagavad Gita 18.29","text":"बुद्धेर्भेदं धृतेश्चैव गुणतस्त्रिविधं शृणु ।\nप्रोच्यमानमशेषेण पृथक्त्वेन धनञ्जय ॥","lang":"sa","roman":"buddherbhedaṃ dhṛteścaiva guṇatastrividhaṃ śṛṇu |\nprocyamānamaśeṣeṇa pṛthaktvena dhanañjaya ||","body":"The division of Reason and of firmness also, threefold according to the qualities, hear thou related, unreservedly and severally, O Dhananjaya.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","29 of 78"]]},"g2-18-29":{"route":"#/gitav/18.29","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:29:en2","title":"Gita 18.29, in another translation","body":"Hear thou the triple distinction of intellect and fortitude, according to the Gunas, as I declare them exhaustively and severally, O Dhananjaya.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","29 of 78"]]},"gv-18-30":{"route":"#/gitav/18.30","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:30:en","title":"Bhagavad Gita 18.30","text":"प्रवृत्तिं च निवृत्तिं च कार्याकार्ये भयाभये ।\nबन्धं मोक्षं च या वेत्ति बुद्धिः सा पार्थ सात्त्विकी ॥","lang":"sa","roman":"pravṛttiṃ ca nivṛttiṃ ca kāryākārye bhayābhaye |\nbandhaṃ mokṣaṃ ca yā vetti buddhiḥ sā pārtha sāttvikī ||","body":"That which knoweth energy and abstinence, what ought to be done and what ought not to be done, fear and fearlessness, bondage and liberation, that Reason is pure, O Pârtha.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","30 of 78"]]},"g2-18-30":{"route":"#/gitav/18.30","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:30:en2","title":"Gita 18.30, in another translation","body":"That which knows the paths of work and renunciation, right and wrong action, fear and fearlessness, bondage and liberation, that intellect, O Pârtha, is Sâttvika.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","30 of 78"]]},"gv-18-31":{"route":"#/gitav/18.31","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:31:en","title":"Bhagavad Gita 18.31","text":"यया धर्ममधर्मं च कार्यं चाकार्यमेव च ।\nअयथावत्प्रजानाति बुद्धिः सा पार्थ राजसी ॥","lang":"sa","roman":"yayā dharmamadharmaṃ ca kāryaṃ cākāryameva ca |\nayathāvatprajānāti buddhiḥ sā pārtha rājasī ||","body":"That by which one understandeth away Right and Wrong and also what ought to be done and what ought not to be done, that Reason, O Pârtha, is passionate.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","31 of 78"]]},"g2-18-31":{"route":"#/gitav/18.31","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:31:en2","title":"Gita 18.31, in another translation","body":"That which has a distorted apprehension of Dharma and its opposite and also of right action and its opposite, that intellect, O Pârtha, is Râjasika.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","31 of 78"]]},"gv-18-32":{"route":"#/gitav/18.32","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:32:en","title":"Bhagavad Gita 18.32","text":"अधर्मं धर्ममिति या मन्यते तमसाऽऽवृता ।\nसर्वार्थान्विपरीतांश्च बुद्धिः सा पार्थ तामसी ॥","lang":"sa","roman":"adharmaṃ dharmamiti yā manyate tamasā’’vṛtā |\nsarvārthānviparītāṃśca buddhiḥ sā pārtha tāmasī ||","body":"That which, enwrapped in darkness, thinketh wrong to be right and seeth all things subverted, that Reason, O Pârtha, is of darkness.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","32 of 78"]]},"g2-18-32":{"route":"#/gitav/18.32","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:32:en2","title":"Gita 18.32, in another translation","body":"That which enveloped in darkness regards Adharma as Dharma and views all things in a perverted light, that intellect, O Pârtha, is Tâmasika.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","32 of 78"]]},"gv-18-33":{"route":"#/gitav/18.33","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:33:en","title":"Bhagavad Gita 18.33","text":"धृत्या यया धारयते मनःप्राणेन्द्रियक्रियाः ।\nयोगेनाव्यभिचारिण्या धृतिः सा पार्थ सात्त्विकी ॥","lang":"sa","roman":"dhṛtyā yayā dhārayate manaḥprāṇendriyakriyāḥ |\nyogenāvyabhicāriṇyā dhṛtiḥ sā pārtha sāttvikī ||","body":"The unwavering firmness by which, through Yoga, one restraineth the activity of the mind, of the life breaths and of the sense-organs, that firmness, O Pârtha, is pure.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","33 of 78"]]},"g2-18-33":{"route":"#/gitav/18.33","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:33:en2","title":"Gita 18.33, in another translation","body":"The fortitude by which the functions of the mind, the Prâna and the senses, O Pârtha, are regulated, that fortitude, unswerving through Yoga, is Sâttvika.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","33 of 78"]]},"gv-18-34":{"route":"#/gitav/18.34","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:34:en","title":"Bhagavad Gita 18.34","text":"यया तु धर्मकामार्थान् धृत्या धारयतेऽर्जुन ।\nप्रसङ्गेन फलाकाङ्क्षी धृतिः सा पार्थ राजसी ॥","lang":"sa","roman":"yayā tu dharmakāmārthān dhṛtyā dhārayate’rjuna |\nprasaṅgena phalākāṅkṣī dhṛtiḥ sā pārtha rājasī ||","body":"But the firmness, O Arjuna, by which, from attachment desirous of fruit, one holdeth fast duty, desire and wealth, that firmness, O Pârtha, is passionate.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","34 of 78"]]},"g2-18-34":{"route":"#/gitav/18.34","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:34:en2","title":"Gita 18.34, in another translation","body":"But the fortitude by which one regulates (one's mind) to Dharma, desire and wealth, desirous of the fruit of each from attachment, that fortitude, O Pârtha, is Râjasika.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","34 of 78"]]},"gv-18-35":{"route":"#/gitav/18.35","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:35:en","title":"Bhagavad Gita 18.35","text":"यया स्वप्नं भयं शोकं विषादं मदमेव च ।\nन विमुञ्चति दुर्मेधा धृतिः सा पार्थ तामसी ॥","lang":"sa","roman":"yayā svapnaṃ bhayaṃ śokaṃ viṣādaṃ madameva ca |\nna vimuñcati durmedhā dhṛtiḥ sā pārtha tāmasī ||","body":"That by which one from stupidity doth not abandon sleep, fear, grief, despair, and also vanity, that firmness, O Pârtha, is dark.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","35 of 78"]]},"g2-18-35":{"route":"#/gitav/18.35","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:35:en2","title":"Gita 18.35, in another translation","body":"That by which a stupid man does not give up sleep, fear, grief, despondency and also overweening conceit, that fortitude, O Pârtha, is Tâmasika.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","35 of 78"]]},"gv-18-36":{"route":"#/gitav/18.36","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:36:en","title":"Bhagavad Gita 18.36","text":"सुखं त्विदानीं त्रिविधं शृणु मे भरतर्षभ ।\nअभ्यासाद्रमते यत्र दुःखान्तं च निगच्छति ॥","lang":"sa","roman":"sukhaṃ tvidānīṃ trividhaṃ śṛṇu me bharatarṣabha |\nabhyāsādramate yatra duḥkhāntaṃ ca nigacchati ||","body":"And now the threefold kinds of pleasure hear thou from Me, O bull of the Bhâratas. That in which one by practice rejoiceth, and which putteth an end to pain;","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","36 of 78"]]},"g2-18-36":{"route":"#/gitav/18.36","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:36:en2","title":"Gita 18.36, in another translation","body":"And now hear from Me, O bull of the Bhâratas, of the threefold happiness. That happiness which one learns to enjoy by habit, and by which one comes to the end of pain;","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","36 of 78"]]},"gv-18-37":{"route":"#/gitav/18.37","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:37:en","title":"Bhagavad Gita 18.37","text":"यत्तदग्रे विषमिव परिणामेऽमृतोपमम् ।\nतत्सुखं सात्त्विकं प्रोक्तमात्मबुद्धिप्रसादजम् ॥","lang":"sa","roman":"yattadagre viṣamiva pariṇāme’mṛtopamam |\ntatsukhaṃ sāttvikaṃ proktamātmabuddhiprasādajam ||","body":"Which at first is as venom but in the end is as nectar; that pleasure is said to be pure, born of the blissful knowledge of the Self.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","37 of 78"]]},"g2-18-37":{"route":"#/gitav/18.37","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:37:en2","title":"Gita 18.37, in another translation","body":"That which is like poison at first, but like nectar at the end; that happiness is declared to be Sâttvika, born of the translucence of intellect due to Self-realisation.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","37 of 78"]]},"gv-18-38":{"route":"#/gitav/18.38","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:38:en","title":"Bhagavad Gita 18.38","text":"विषयेन्द्रियसंयोगाद्यत्तदग्रेऽमृतोपमम् ।\nपरिणामे विषमिव तत्सुखं राजसं स्मृतम् ॥","lang":"sa","roman":"viṣayendriyasaṃyogādyattadagre’mṛtopamam |\npariṇāme viṣamiva tatsukhaṃ rājasaṃ smṛtam ||","body":"That which from the union of the senses with their objects at first is as nectar, but in the end is like venom, that pleasure is accounted passionate.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","38 of 78"]]},"g2-18-38":{"route":"#/gitav/18.38","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:38:en2","title":"Gita 18.38, in another translation","body":"That which arises from the contact of object with sense, at first like nectar, but at the end like poison, that happiness is declared to be Râjasika.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","38 of 78"]]},"gv-18-39":{"route":"#/gitav/18.39","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:39:en","title":"Bhagavad Gita 18.39","text":"यदग्रे चानुबन्धे च सुखं मोहनमात्मनः ।\nनिद्रालस्यप्रमादोत्थं तत्तामसमुदाहृतम् ॥","lang":"sa","roman":"yadagre cānubandhe ca sukhaṃ mohanamātmanaḥ |\nnidrālasyapramādotthaṃ tattāmasamudāhṛtam ||","body":"That pleasure which both at first and afterwards is delusive of the self, arising from sleep, indolence and heedlessness, that is declared dark.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","39 of 78"]]},"g2-18-39":{"route":"#/gitav/18.39","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:39:en2","title":"Gita 18.39, in another translation","body":"That happiness which begins and results in self-delusion arising from sleep, indolence and miscomprehension, that is declared to be Tâmasika.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","39 of 78"]]},"gv-18-40":{"route":"#/gitav/18.40","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:40:en","title":"Bhagavad Gita 18.40","text":"न तदस्ति पृथिव्यां वा दिवि देवेषु वा पुनः ।\nसत्त्वं प्रकृतिजैर्मुक्तं यदेभिः स्यात्त्रिभिर्गुणैः ॥","lang":"sa","roman":"na tadasti pṛthivyāṃ vā divi deveṣu vā punaḥ |\nsattvaṃ prakṛtijairmuktaṃ yadebhiḥ syāttribhirguṇaiḥ ||","body":"There is not an entity, either on the earth or again in heaven among the Shining Ones, that is liberated from these three qualities, born of Matter.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","40 of 78"]]},"g2-18-40":{"route":"#/gitav/18.40","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:40:en2","title":"Gita 18.40, in another translation","body":"There is no entity on earth, or again in heaven among the Devas, that is devoid of these three Gunas, born of Prakriti.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","40 of 78"]]},"gv-18-41":{"route":"#/gitav/18.41","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:41:en","title":"Bhagavad Gita 18.41","text":"ब्राह्मणक्षत्रियविशां शूद्राणां च परंतप ।\nकर्माणि प्रविभक्तानि स्वभावप्रभवैर्गुणैः ॥","lang":"sa","roman":"brāhmaṇakṣatriyaviśāṃ śūdrāṇāṃ ca paraṃtapa |\nkarmāṇi pravibhaktāni svabhāvaprabhavairguṇaiḥ ||","body":"Of Brâhmanas, Kshattriyas, Vaishyas and Shûdras, O Parantapa, the duties have been distributed, according to the qualities born of their own natures.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","41 of 78"]]},"g2-18-41":{"route":"#/gitav/18.41","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:41:en2","title":"Gita 18.41, in another translation","body":"Of Brâhmanas and Kshatriyas and Vaishyas, as also of Sudras, O scorcher of foes, the duties are distributed according to the Gunas born of their own nature.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","41 of 78"]]},"gv-18-42":{"route":"#/gitav/18.42","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:42:en","title":"Bhagavad Gita 18.42","text":"शमो दमस्तपः शौचं क्षान्तिरार्जवमेव च ।\nज्ञानं विज्ञानमास्तिक्यं ब्रह्मकर्म स्वभावजम् ॥","lang":"sa","roman":"śamo damastapaḥ śaucaṃ kṣāntirārjavameva ca |\njñānaṃ vijñānamāstikyaṃ brahmakarma svabhāvajam ||","body":"Serenity, self-restraint, austerity, purity, forgiveness and also uprightness, wisdom, knowledge, belief in God, are the Brâhmana duty, born of his own nature.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","42 of 78"]]},"g2-18-42":{"route":"#/gitav/18.42","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:42:en2","title":"Gita 18.42, in another translation","body":"The control of the mind and the senses, austerity, purity, forbearance, and also uprightness, knowledge, realisation, belief in a hereafter,—these are the duties of the Brâhmanas, born of (their own) nature.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","42 of 78"]]},"gv-18-43":{"route":"#/gitav/18.43","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:43:en","title":"Bhagavad Gita 18.43","text":"शौर्यं तेजो धृतिर्दाक्ष्यं युद्धे चाप्यपलायनम् ।\nदानमीश्वरभावश्च क्षात्रं कर्म स्वभावजम् ॥","lang":"sa","roman":"śauryaṃ tejo dhṛtirdākṣyaṃ yuddhe cāpyapalāyanam |\ndānamīśvarabhāvaśca kṣātraṃ karma svabhāvajam ||","body":"Prowess, splendour, firmness, dexterity, and also not flying from battle, generosity, the nature of a ruler, are the Kshattriya duty, born of his own nature.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","43 of 78"]]},"g2-18-43":{"route":"#/gitav/18.43","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:43:en2","title":"Gita 18.43, in another translation","body":"Prowess, boldness, fortitude, dexterity, and also not flying from battle, generosity and sovereignty are the duties of the Kshatriyas, born of (their own) nature.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","43 of 78"]]},"gv-18-44":{"route":"#/gitav/18.44","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:44:en","title":"Bhagavad Gita 18.44","text":"कृषिगौरक्ष्यवाणिज्यं वैश्यकर्म स्वभावजम् ।\nपरिचर्यात्मकं कर्म शूद्रस्यापि स्वभावजम् ॥","lang":"sa","roman":"kṛṣigaurakṣyavāṇijyaṃ vaiśyakarma svabhāvajam |\nparicaryātmakaṃ karma śūdrasyāpi svabhāvajam ||","body":"Ploughing, protection of kine, and trade are the Vaishya duty, born of his own nature. Action of the nature of service is the Shûdra duty, born of his own nature.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","44 of 78"]]},"g2-18-44":{"route":"#/gitav/18.44","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:44:en2","title":"Gita 18.44, in another translation","body":"Agriculture, cattle-rearing and trade are the duties of the Vaishyas, born of (their own) nature; and action consisting of service is the duty of the Sudras, born of (their own) nature.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","44 of 78"]]},"gv-18-45":{"route":"#/gitav/18.45","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:45:en","title":"Bhagavad Gita 18.45","text":"स्वे स्वे कर्मण्यभिरतः संसिद्धिं लभते नरः ।\nस्वकर्मनिरतः सिद्धिं यथा विन्दति तच्छृणु ॥","lang":"sa","roman":"sve sve karmaṇyabhirataḥ saṃsiddhiṃ labhate naraḥ |\nsvakarmanirataḥ siddhiṃ yathā vindati tacchṛṇu ||","body":"Man reacheth perfection by each being intent on his own duty. Listen thou how perfection is won by him who is intent on his own duty.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","45 of 78"]]},"g2-18-45":{"route":"#/gitav/18.45","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:45:en2","title":"Gita 18.45, in another translation","body":"Devoted each to his own duty, man attains the highest perfection. How engaged in his own duty, he attains perfection, that hear.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","45 of 78"]]},"gv-18-46":{"route":"#/gitav/18.46","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:46:en","title":"Bhagavad Gita 18.46","text":"यतः प्रवृत्तिर्भूतानां येन सर्वमिदं ततम् ।\nस्वकर्मणा तमभ्यर्च्य सिद्धिं विन्दति मानवः ॥","lang":"sa","roman":"yataḥ pravṛttirbhūtānāṃ yena sarvamidaṃ tatam |\nsvakarmaṇā tamabhyarcya siddhiṃ vindati mānavaḥ ||","body":"He from whom is the emanation of beings, by Whom all This is pervaded, by worshipping Him in his own duty a man winneth perfection.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","46 of 78"]]},"g2-18-46":{"route":"#/gitav/18.46","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:46:en2","title":"Gita 18.46, in another translation","body":"From whom is the evolution of all beings, by whom all this is pervaded, worshipping Him with his own duty, a man attains perfection.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","46 of 78"]]},"gv-18-47":{"route":"#/gitav/18.47","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:47:en","title":"Bhagavad Gita 18.47","text":"श्रेयान्स्वधर्मो विगुणः परधर्मात्स्वनुष्ठितात् ।\nस्वभावनियतं कर्म कुर्वन्नाप्नोति किल्बिषम् ॥","lang":"sa","roman":"śreyānsvadharmo viguṇaḥ paradharmātsvanuṣṭhitāt |\nsvabhāvaniyataṃ karma kurvannāpnoti kilbiṣam ||","body":"Better is one's own duty though destitute of merits than the well-executed duty of another. He who doeth the duty laid down by his own nature incurreth not sin.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","47 of 78"]]},"g2-18-47":{"route":"#/gitav/18.47","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:47:en2","title":"Gita 18.47, in another translation","body":"Better is one's own Dharma, (though) imperfect, than the Dharma of another well-performed. He who does the duty ordained by his own nature incurs no evil.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","47 of 78"]]},"gv-18-48":{"route":"#/gitav/18.48","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:48:en","title":"Bhagavad Gita 18.48","text":"सहजं कर्म कौन्तेय सदोषमपि न त्यजेत् ।\nसर्वारम्भा हि दोषेण धूमेनाग्निरिवावृताः ॥","lang":"sa","roman":"sahajaṃ karma kaunteya sadoṣamapi na tyajet |\nsarvārambhā hi doṣeṇa dhūmenāgnirivāvṛtāḥ ||","body":"Congenital duty, O son of Kunti, though defective, ought not to be abandoned. All undertakings indeed are clouded by defects as fire by smoke.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","48 of 78"]]},"g2-18-48":{"route":"#/gitav/18.48","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:48:en2","title":"Gita 18.48, in another translation","body":"One should not relinquish, O son of Kunti, the duty to which one is born, though it is attended with evil; for, all undertakings are enveloped by evil, as fire by smoke.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","48 of 78"]]},"gv-18-49":{"route":"#/gitav/18.49","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:49:en","title":"Bhagavad Gita 18.49","text":"असक्तबुद्धिः सर्वत्र जितात्मा विगतस्पृहः ।\nनैष्कर्म्यसिद्धिं परमां संन्यासेनाधिगच्छति ॥","lang":"sa","roman":"asaktabuddhiḥ sarvatra jitātmā vigataspṛhaḥ |\nnaiṣkarmyasiddhiṃ paramāṃ saṃnyāsenādhigacchati ||","body":"He whose Reason is everywhere unattached, the self-subdued, dead to desires, he goeth by renunciation to the supreme perfection of freedom from obligation.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","49 of 78"]]},"g2-18-49":{"route":"#/gitav/18.49","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:49:en2","title":"Gita 18.49, in another translation","body":"He whose intellect is unattached everywhere, who has subdued his heart, whose desires have fled, he attains by renunciation to the supreme perfection, consisting of freedom from action.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","49 of 78"]]},"gv-18-50":{"route":"#/gitav/18.50","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:50:en","title":"Bhagavad Gita 18.50","text":"सिद्धिं प्राप्तो यथा ब्रह्म तथाप्नोति निबोध मे ।\nसमासेनैव कौन्तेय निष्ठा ज्ञानस्य या परा ॥","lang":"sa","roman":"siddhiṃ prāpto yathā brahma tathāpnoti nibodha me |\nsamāsenaiva kaunteya niṣṭhā jñānasya yā parā ||","body":"How he who hath attained perfection obtaineth the Eternal, that highest state of wisdom, learn thou from Me only succinctly, O Kaunteya.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","50 of 78"]]},"g2-18-50":{"route":"#/gitav/18.50","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:50:en2","title":"Gita 18.50, in another translation","body":"Learn from Me in brief, O son of Kunti, how reaching such perfection, he attains to Brahman, that supreme consummation of knowledge.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","50 of 78"]]},"gv-18-51":{"route":"#/gitav/18.51","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:51:en","title":"Bhagavad Gita 18.51","text":"बुद्ध्या विशुद्धया युक्तो धृत्याऽऽत्मानं नियम्य च ।\nशब्दादीन् विषयांस्त्यक्त्वा रागद्वेषौ व्युदस्य च ॥","lang":"sa","roman":"buddhyā viśuddhayā yukto dhṛtyā’’tmānaṃ niyamya ca |\nśabdādīn viṣayāṃstyaktvā rāgadveṣau vyudasya ca ||","body":"United to this Reason, purified, controlling the self by firmness, having abandoned sound and the other objects of the senses, having laid aside passion and malice,","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","51 of 78"]]},"g2-18-51":{"route":"#/gitav/18.51","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:51:en2","title":"Gita 18.51, in another translation","body":"Endued with a pure intellect, subduing the body and the senses with fortitude, relinquishing sound and such other sense-objects, abandoning attraction and hatred;","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","51 of 78"]]},"gv-18-52":{"route":"#/gitav/18.52","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:52:en","title":"Bhagavad Gita 18.52","text":"विविक्तसेवी लघ्वाशी यतवाक्कायमानसः ।\nध्यानयोगपरो नित्यं वैराग्यं समुपाश्रितः ॥","lang":"sa","roman":"viviktasevī laghvāśī yatavākkāyamānasaḥ |\ndhyānayogaparo nityaṃ vairāgyaṃ samupāśritaḥ ||","body":"Dwelling in solitude, abstemious, speech, body and mind subdued, constantly fixed in meditation and yoga, taking refuge in dispassion,","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","52 of 78"]]},"g2-18-52":{"route":"#/gitav/18.52","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:52:en2","title":"Gita 18.52, in another translation","body":"Resorting to a sequestered spot, eating but little, body, speech and mind controlled, ever engaged in meditation and concentration, possessed of dispassion;","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","52 of 78"]]},"gv-18-53":{"route":"#/gitav/18.53","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:53:en","title":"Bhagavad Gita 18.53","text":"अहङ्कारं बलं दर्पं कामं क्रोधं परिग्रहम् ।\nविमुच्य निर्ममः शान्तो ब्रह्मभूयाय कल्पते ॥","lang":"sa","roman":"ahaṅkāraṃ balaṃ darpaṃ kāmaṃ krodhaṃ parigraham |\nvimucya nirmamaḥ śānto brahmabhūyāya kalpate ||","body":"Having cast aside egoism, violence, arrogance, desire, wrath, covetousness, selfless and peaceful—he is fit to become the Eternal.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","53 of 78"]]},"g2-18-53":{"route":"#/gitav/18.53","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:53:en2","title":"Gita 18.53, in another translation","body":"Forsaking egoism, power, pride, lust, wrath and property, freed from the notion of \"mine,\" and tranquil, he is fit for becoming Brahman.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","53 of 78"]]},"gv-18-54":{"route":"#/gitav/18.54","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:54:en","title":"Bhagavad Gita 18.54","text":"ब्रह्मभूतः प्रसन्नात्मा न शोचति न काङ्क्षति ।\nसमः सर्वेषु भूतेषु मद्भक्तिं लभते पराम् ॥","lang":"sa","roman":"brahmabhūtaḥ prasannātmā na śocati na kāṅkṣati |\nsamaḥ sarveṣu bhūteṣu madbhaktiṃ labhate parām ||","body":"Becoming the Eternal, serene in the Self, he neither grieveth nor desireth; the same to all beings, he obtaineth supreme devotion unto Me.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","54 of 78"]]},"g2-18-54":{"route":"#/gitav/18.54","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:54:en2","title":"Gita 18.54, in another translation","body":"Brahman-become, tranquil-minded, he neither grieves nor desires; the same to all beings, he attains to supreme devotion unto Me.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","54 of 78"]]},"gv-18-55":{"route":"#/gitav/18.55","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:55:en","title":"Bhagavad Gita 18.55","text":"भक्त्या मामभिजानाति यावान्यश्चास्मि तत्त्वतः ।\nततो मां तत्त्वतो ज्ञात्वा विशते तदनन्तरम् ॥","lang":"sa","roman":"bhaktyā māmabhijānāti yāvānyaścāsmi tattvataḥ |\ntato māṃ tattvato jñātvā viśate tadanantaram ||","body":"By devotion he knoweth Me in essence, who and what I am; having thus known Me in essence he forthwith entereth into the Supreme.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","55 of 78"]]},"g2-18-55":{"route":"#/gitav/18.55","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:55:en2","title":"Gita 18.55, in another translation","body":"By devotion he knows Me in reality, what and who I am; then having known Me in reality, he forthwith enters into Me.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","55 of 78"]]},"gv-18-56":{"route":"#/gitav/18.56","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:56:en","title":"Bhagavad Gita 18.56","text":"सर्वकर्माण्यपि सदा कुर्वाणो मद्व्यपाश्रयः ।\nमत्प्रसादादवाप्नोति शाश्वतं पदमव्ययम् ॥","lang":"sa","roman":"sarvakarmāṇyapi sadā kurvāṇo madvyapāśrayaḥ |\nmatprasādādavāpnoti śāśvataṃ padamavyayam ||","body":"Though ever performing all actions, taking refuge in Me, by My grace he obtaineth the eternal indestructible abode.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","56 of 78"]]},"g2-18-56":{"route":"#/gitav/18.56","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:56:en2","title":"Gita 18.56, in another translation","body":"Even doing all actions always, taking refuge in Me,—by My grace he attains to the eternal, immutable State.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","56 of 78"]]},"gv-18-57":{"route":"#/gitav/18.57","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:57:en","title":"Bhagavad Gita 18.57","text":"चेतसा सर्वकर्माणि मयि संन्यस्य मत्परः ।\nबुद्धियोगमुपाश्रित्य मच्चित्तः सततं भव ॥","lang":"sa","roman":"cetasā sarvakarmāṇi mayi saṃnyasya matparaḥ |\nbuddhiyogamupāśritya maccittaḥ satataṃ bhava ||","body":"Renouncing mentally all works in Me, intent on Me, resorting to the yoga of discrimination, have thy thought ever on Me.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","57 of 78"]]},"g2-18-57":{"route":"#/gitav/18.57","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:57:en2","title":"Gita 18.57, in another translation","body":"Resigning mentally all deeds to Me, having Me as the highest goal, resorting to Buddhi-Yoga do thou ever fix thy mind on Me.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","57 of 78"]]},"gv-18-58":{"route":"#/gitav/18.58","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:58:en","title":"Bhagavad Gita 18.58","text":"मच्चित्तः सर्वदुर्गाणि मत्प्रसादात्तरिष्यसि ।\nअथ चेत्त्वमहङ्कारान्न श्रोष्यसि विनङ्क्ष्यसि ॥","lang":"sa","roman":"maccittaḥ sarvadurgāṇi matprasādāttariṣyasi |\natha cettvamahaṅkārānna śroṣyasi vinaṅkṣyasi ||","body":"Thinking on Me, thou shalt overcome all obstacles by My grace: but if from egoism thou wilt not listen, thou shalt be destroyed utterly.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","58 of 78"]]},"g2-18-58":{"route":"#/gitav/18.58","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:58:en2","title":"Gita 18.58, in another translation","body":"Fixing thy mind on Me, thou shalt, by My grace, overcome all obstacles; but if from self-conceit thou wilt not hear Me, thou shalt perish.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","58 of 78"]]},"gv-18-59":{"route":"#/gitav/18.59","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:59:en","title":"Bhagavad Gita 18.59","text":"यदहङ्कारमाश्रित्य न योत्स्य इति मन्यसे ।\nमिथ्यैष व्यवसायस्ते प्रकृतिस्त्वां नियोक्ष्यति ॥","lang":"sa","roman":"yadahaṅkāramāśritya na yotsya iti manyase |\nmithyaiṣa vyavasāyaste prakṛtistvāṃ niyokṣyati ||","body":"Entrenched in egoism, thou thinkest, \"I will not fight;\" to no purpose thy determination; nature will constrain thee.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","59 of 78"]]},"g2-18-59":{"route":"#/gitav/18.59","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:59:en2","title":"Gita 18.59, in another translation","body":"If filled with self-conceit thou thinkest, \"I will not fight,\" vain is this thy resolve; thy Prakriti will constrain thee.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","59 of 78"]]},"gv-18-60":{"route":"#/gitav/18.60","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:60:en","title":"Bhagavad Gita 18.60","text":"स्वभावजेन कौन्तेय निबद्धः स्वेन कर्मणा ।\nकर्तुं नेच्छसि यन्मोहात्करिष्यस्यवशोऽपि तत् ॥","lang":"sa","roman":"svabhāvajena kaunteya nibaddhaḥ svena karmaṇā |\nkartuṃ necchasi yanmohātkariṣyasyavaśo’pi tat ||","body":"O son of Kuntî, bound by thine own duty born of thine own nature, that which from delusion thou desirest not to do, even that helplessly thou shalt perform.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","60 of 78"]]},"g2-18-60":{"route":"#/gitav/18.60","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:60:en2","title":"Gita 18.60, in another translation","body":"Fettered, O son of Kunti, by thy own Karma, born of thy own nature, what thou, from delusion, desirest not to do, thou shalt have to do in spite of thyself.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","60 of 78"]]},"gv-18-61":{"route":"#/gitav/18.61","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:61:en","title":"Bhagavad Gita 18.61","text":"ईश्वरः सर्वभूतानां हृद्देशेऽर्जुन तिष्ठति ।\nभ्रामयन्सर्वभूतानि यन्त्रारूढानि मायया ॥","lang":"sa","roman":"īśvaraḥ sarvabhūtānāṃ hṛddeśe’rjuna tiṣṭhati |\nbhrāmayansarvabhūtāni yantrārūḍhāni māyayā ||","body":"The Lord dwelleth in the hearts of all beings, O Arjuna, by His illusive Power causing all beings to revolve, as though mounted on a potter's wheel.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","61 of 78"]]},"g2-18-61":{"route":"#/gitav/18.61","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:61:en2","title":"Gita 18.61, in another translation","body":"The Lord, O Arjuna, dwells in the hearts of all beings, causing all beings, by His Mâyâ, to revolve, (as if) mounted on a machine.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","61 of 78"]]},"gv-18-62":{"route":"#/gitav/18.62","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:62:en","title":"Bhagavad Gita 18.62","text":"तमेव शरणं गच्छ सर्वभावेन भारत ।\nतत्प्रसादात्परां शान्तिं स्थानं प्राप्स्यसि शाश्वतम् ॥","lang":"sa","roman":"tameva śaraṇaṃ gaccha sarvabhāvena bhārata |\ntatprasādātparāṃ śāntiṃ sthānaṃ prāpsyasi śāśvatam ||","body":"Flee unto Him for shelter with all thy being, O Bhârata; by His grace thou shalt obtain supreme peace, the everlasting dwelling-place.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","62 of 78"]]},"g2-18-62":{"route":"#/gitav/18.62","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:62:en2","title":"Gita 18.62, in another translation","body":"Take refuge in Him with all thy heart, O Bhârata; by His grace shalt thou attain supreme peace (and) the eternal abode.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","62 of 78"]]},"gv-18-63":{"route":"#/gitav/18.63","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:63:en","title":"Bhagavad Gita 18.63","text":"इति ते ज्ञानमाख्यातं गुह्याद्गुह्यतरं मया ।\nविमृश्यैतदशेषेण यथेच्छसि तथा कुरु ॥","lang":"sa","roman":"iti te jñānamākhyātaṃ guhyādguhyataraṃ mayā |\nvimṛśyaitadaśeṣeṇa yathecchasi tathā kuru ||","body":"Thus hath wisdom, more secret than secrecy itself, been declared unto thee by Me; having reflected on it fully, then act thou as thou listest.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","63 of 78"]]},"g2-18-63":{"route":"#/gitav/18.63","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:63:en2","title":"Gita 18.63, in another translation","body":"Thus has wisdom more profound than all profundities, been declared to. thee by Me; reflecting over it fully, act as thou likest.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","63 of 78"]]},"gv-18-64":{"route":"#/gitav/18.64","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:64:en","title":"Bhagavad Gita 18.64","text":"सर्वगुह्यतमं भूयः शृणु मे परमं वचः ।\nइष्टोऽसि मे दृढमिति ततो वक्ष्यामि ते हितम् ॥","lang":"sa","roman":"sarvaguhyatamaṃ bhūyaḥ śṛṇu me paramaṃ vacaḥ |\niṣṭo’si me dṛḍhamiti tato vakṣyāmi te hitam ||","body":"Listen thou again to My supreme word, most secret of all; beloved art thou of Me, and steadfast of heart, therefore will I speak for thy benefit.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","64 of 78"]]},"g2-18-64":{"route":"#/gitav/18.64","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:64:en2","title":"Gita 18.64, in another translation","body":"Hear thou again My supreme word, the profoundest of all; because thou art dearly beloved of Me, therefore will I speak what is good to thee.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","64 of 78"]]},"gv-18-65":{"route":"#/gitav/18.65","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:65:en","title":"Bhagavad Gita 18.65","text":"मन्मना भव मद्भक्तो मद्याजी मां नमस्कुरु ।\nमामेवैष्यसि सत्यं ते प्रतिजाने प्रियोऽसि मे ॥","lang":"sa","roman":"manmanā bhava madbhakto madyājī māṃ namaskuru |\nmāmevaiṣyasi satyaṃ te pratijāne priyo’si me ||","body":"Merge thy mind in Me, be my devotee, sacrifice to Me, prostrate thyself before Me, thou shalt come even to Me. I pledge thee My troth; thou art dear to Me.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","65 of 78"]]},"g2-18-65":{"route":"#/gitav/18.65","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:65:en2","title":"Gita 18.65, in another translation","body":"Occupy thy mind with Me, be devoted to Me, sacrifice to Me, bow down to Me. Thou shalt reach Myself; truly do I promise unto thee, (for) thou art dear to Me.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","65 of 78"]]},"gv-18-66":{"route":"#/gitav/18.66","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:66:en","title":"Bhagavad Gita 18.66","text":"सर्वधर्मान्परित्यज्य मामेकं शरणं व्रज ।\nअहं त्वा सर्वपापेभ्यो मोक्षयिष्यामि मा शुचः ॥","lang":"sa","roman":"sarvadharmānparityajya māmekaṃ śaraṇaṃ vraja |\nahaṃ tvā sarvapāpebhyo mokṣayiṣyāmi mā śucaḥ ||","body":"Abandoning all duties come unto Me alone for shelter; sorrow not, I will liberate thee from all sins.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","66 of 78"]]},"g2-18-66":{"route":"#/gitav/18.66","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:66:en2","title":"Gita 18.66, in another translation","body":"Relinquishing all Dharmas take refuge in Me alone; I will liberate thee from all sins; grieve not.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","66 of 78"]]},"gv-18-67":{"route":"#/gitav/18.67","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:67:en","title":"Bhagavad Gita 18.67","text":"इदं ते नातपस्काय नाभक्ताय कदाचन ।\nन चाशुश्रूषवे वाच्यं न च मां योऽभ्यसूयति ॥","lang":"sa","roman":"idaṃ te nātapaskāya nābhaktāya kadācana |\nna cāśuśrūṣave vācyaṃ na ca māṃ yo’bhyasūyati ||","body":"Never is this to be spoken by thee to anyone who is without asceticism, nor without devotion, nor to one who desireth not to listen, nor yet to him who speaketh evil of Me.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","67 of 78"]]},"g2-18-67":{"route":"#/gitav/18.67","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:67:en2","title":"Gita 18.67, in another translation","body":"This is never to be spoken by thee to one who is devoid of austerities or devotion, nor to one who does not render service, nor to one who cavils at Me.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","67 of 78"]]},"gv-18-68":{"route":"#/gitav/18.68","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:68:en","title":"Bhagavad Gita 18.68","text":"य इमं परमं गुह्यं मद्भक्तेष्वभिधास्यति ।\nभक्तिं मयि परां कृत्वा मामेवैष्यत्यसंशयः ॥","lang":"sa","roman":"ya imaṃ paramaṃ guhyaṃ madbhakteṣvabhidhāsyati |\nbhaktiṃ mayi parāṃ kṛtvā māmevaiṣyatyasaṃśayaḥ ||","body":"He who shall declare this supreme secret among My devotees, having shown the highest devotion for Me, without doubt he shall come to Me.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","68 of 78"]]},"g2-18-68":{"route":"#/gitav/18.68","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:68:en2","title":"Gita 18.68, in another translation","body":"He who with supreme devotion to Me will teach this deeply profound philosophy to My devotees, shall doubtless come to Me alone.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","68 of 78"]]},"gv-18-69":{"route":"#/gitav/18.69","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:69:en","title":"Bhagavad Gita 18.69","text":"न च तस्मान्मनुष्येषु कश्चिन्मे प्रियकृत्तमः ।\nभविता न च मे तस्मादन्यः प्रियतरो भुवि ॥","lang":"sa","roman":"na ca tasmānmanuṣyeṣu kaścinme priyakṛttamaḥ |\nbhavitā na ca me tasmādanyaḥ priyataro bhuvi ||","body":"Nor is there any among men who performeth dearer service to Me than he, nor any other shall be more beloved by Me on earth than he.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","69 of 78"]]},"g2-18-69":{"route":"#/gitav/18.69","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:69:en2","title":"Gita 18.69, in another translation","body":"Nor among men is there any who does dearer service to Me, nor shall there be another on earth dearer to Me, than he.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","69 of 78"]]},"gv-18-70":{"route":"#/gitav/18.70","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:70:en","title":"Bhagavad Gita 18.70","text":"अध्येष्यते च य इमं धर्म्यं संवादमावयोः ।\nज्ञानयज्ञेन तेनाहमिष्टः स्यामिति मे मतिः ॥","lang":"sa","roman":"adhyeṣyate ca ya imaṃ dharmyaṃ saṃvādamāvayoḥ |\njñānayajñena tenāhamiṣṭaḥ syāmiti me matiḥ ||","body":"And he who shall study this sacred dialogue of ours, by him I shall be worshipped with the sacrifice of wisdom. Such is My mind.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","70 of 78"]]},"g2-18-70":{"route":"#/gitav/18.70","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:70:en2","title":"Gita 18.70, in another translation","body":"And he who will study this sacred dialogue of ours, by him shall I have been worshipped by the Yajna of knowledge; such is My conviction.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","70 of 78"]]},"gv-18-71":{"route":"#/gitav/18.71","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:71:en","title":"Bhagavad Gita 18.71","text":"श्रद्धावाननसूयश्च शृणुयादपि यो नरः ।\nसोऽपि मुक्तः शुभाँल्लोकान्प्राप्नुयात्पुण्यकर्मणाम् ॥","lang":"sa","roman":"śraddhāvānanasūyaśca śṛṇuyādapi yo naraḥ |\nso’pi muktaḥ śubhām̐llokānprāpnuyātpuṇyakarmaṇām ||","body":"The man also who, full of faith, merely heareth it unreviling, even he, freed from evil, obtaineth the radiant worlds of the righteous.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","71 of 78"]]},"g2-18-71":{"route":"#/gitav/18.71","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:71:en2","title":"Gita 18.71, in another translation","body":"And even that man who hears this, full of Shraddhâ and free from malice, he too, liberated, shall attain to the happy worlds of those of righteous deeds.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","71 of 78"]]},"gv-18-72":{"route":"#/gitav/18.72","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:72:en","title":"Bhagavad Gita 18.72","text":"कच्चिदेतच्छ्रुतं पार्थ त्वयैकाग्रेण चेतसा ।\nकच्चिदज्ञानसंमोहः प्रनष्टस्ते धनञ्जय ॥","lang":"sa","roman":"kaccidetacchrutaṃ pārtha tvayaikāgreṇa cetasā |\nkaccidajñānasaṃmohaḥ pranaṣṭaste dhanañjaya ||","body":"Hath this been heard, O son of Prithâ, with one-pointed mind? Has thy delusion, caused by unwisdom, been destroyed, O Dhananjaya?","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","72 of 78"]]},"g2-18-72":{"route":"#/gitav/18.72","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:72:en2","title":"Gita 18.72, in another translation","body":"Has this been heard by thee, Pârtha, with an attentive mind? Has the delusion of thy ignorance been destroyed, O Dhananjaya?","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","72 of 78"]]},"gv-18-73":{"route":"#/gitav/18.73","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:73:en","title":"Bhagavad Gita 18.73","text":"नष्टो मोहः स्मृतिर्लब्धा त्वत्प्रसादान्मयाच्युत ।\nस्थितोऽस्मि गतसन्देहः करिष्ये वचनं तव ॥","lang":"sa","roman":"naṣṭo mohaḥ smṛtirlabdhā tvatprasādānmayācyuta |\nsthito’smi gatasandehaḥ kariṣye vacanaṃ tava ||","body":"Arjuna said: Destroyed is my delusion. I have gained knowledge through Thy grace, O Immutable one. I am firm, my doubts have fled away. I will do according to Thy word.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","73 of 78"]]},"g2-18-73":{"route":"#/gitav/18.73","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:73:en2","title":"Gita 18.73, in another translation","body":"Destroyed is my delusion, and I have gained my memory through Thy grace, O Achyuta. I am firm; my doubts are gone. I will do Thy word.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","73 of 78"]]},"gv-18-74":{"route":"#/gitav/18.74","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:74:en","title":"Bhagavad Gita 18.74","text":"इत्यहं वासुदेवस्य पार्थस्य च महात्मनः ।\nसंवादमिममश्रौषमद्भुतं रोमहर्षणम् ॥","lang":"sa","roman":"ityahaṃ vāsudevasya pārthasya ca mahātmanaḥ |\nsaṃvādamimamaśrauṣamadbhutaṃ romaharṣaṇam ||","body":"Sanjaya said: I heard this marvellous dialogue of Vâsudeva, and of the great-souled Partha, causing my hair to stand on end.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","74 of 78"]]},"g2-18-74":{"route":"#/gitav/18.74","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:74:en2","title":"Gita 18.74, in another translation","body":"Thus have I heard this wonderful dialogue between Vâsudeva and the high-souled Pârtha, causing my hair to stand on end.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","74 of 78"]]},"gv-18-75":{"route":"#/gitav/18.75","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:75:en","title":"Bhagavad Gita 18.75","text":"व्यासप्रसादाच्छ्रुतवानेतद्गुह्यमहं परम् ।\nयोगं योगेश्वरात्कृष्णात्साक्षात्कथयतः स्वयम् ॥","lang":"sa","roman":"vyāsaprasādācchrutavānetadguhyamahaṃ param |\nyogaṃ yogeśvarātkṛṣṇātsākṣātkathayataḥ svayam ||","body":"By the favour of Vyâsa I listened to this secret and supreme yoga from the Lord of Yoga, Krishna Himself, speaking before mine eyes.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","75 of 78"]]},"g2-18-75":{"route":"#/gitav/18.75","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:75:en2","title":"Gita 18.75, in another translation","body":"Through the grace of Vyâsa have I heard this supreme and most profound Yoga, direct from Krishna, the Lord of Yoga, Himself declaring it.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","75 of 78"]]},"gv-18-76":{"route":"#/gitav/18.76","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:76:en","title":"Bhagavad Gita 18.76","text":"राजन्संस्मृत्य संस्मृत्य संवादमिममद्भुतम् ।\nकेशवार्जुनयोः पुण्यं हृष्यामि च मुहुर्मुहुः ॥","lang":"sa","roman":"rājansaṃsmṛtya saṃsmṛtya saṃvādamimamadbhutam |\nkeśavārjunayoḥ puṇyaṃ hṛṣyāmi ca muhurmuhuḥ ||","body":"O King, remembering, remembering this marvellous and holy dialogue between Keshava and Arjuna, I rejoice again and again.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","76 of 78"]]},"g2-18-76":{"route":"#/gitav/18.76","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:76:en2","title":"Gita 18.76, in another translation","body":"O King, as I remember and remember this wonderful and holy dialogue between Keshava and Arjuna, I rejoice again and again.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","76 of 78"]]},"gv-18-77":{"route":"#/gitav/18.77","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:77:en","title":"Bhagavad Gita 18.77","text":"तच्च संस्मृत्य संस्मृत्य रूपमत्यद्भुतं हरेः ।\nविस्मयो मे महान् राजन् हृष्यामि च पुनः पुनः ॥","lang":"sa","roman":"tacca saṃsmṛtya saṃsmṛtya rūpamatyadbhutaṃ hareḥ |\nvismayo me mahān rājan hṛṣyāmi ca punaḥ punaḥ ||","body":"Remembering, remembering, also that most marvellous form of Hari, great is my wonder, O King. I rejoice, again and again.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","77 of 78"]]},"g2-18-77":{"route":"#/gitav/18.77","art":null,"source":"Sanskrit: the vulgate text of the IIT Kanpur Gita Supersite via gita/gita (public domain), checked against three other editions. English: Annie Besant (1922) and Swami Swarupananda (1909), both public domain.","cta":"Open this verse","why":"The Bhagavad Gita, chapter 18 — The Way of Liberation in Renunciation","src":"gita:18:77:en2","title":"Gita 18.77, in another translation","body":"And as I remember and remember that most wonderful Form of Hari, great is my wonder, O King; and I rejoice again and again.","facts":[["Chapter","The Way of Liberation in Renunciation"],["Verse","77 of 78"]]}});
